import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation: agent_id -> [cooperate_count, defect_count, total_interactions]
        self.reputations = {}
        # Personal trust: agent_id -> score (positive good, negative bad)
        self.trust = {}
        # Track own cooperation rate
        self.own_coop = 0
        self.own_defect = 0
        # Track recent outcomes for adaptation
        self.recent_scores = []
        self.coop_recent = 0
        self.defect_recent = 0
        # Adjustment factor for threshold
        self.threshold = 0.3
        self.rounds = 0
        self.gen = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None or opponent == self.agent_id:
            return True
        # Get reputation of opponent
        rep = self.reputations.get(opponent, {'c': 0, 'd': 0, 'n': 0})
        n = rep['n']
        if n == 0:
            coop_prob = 0.5  # unknown, be cautious
        else:
            coop_rate = rep['c'] / n
            # Adjust based on personal trust
            trust_score = self.trust.get(opponent, 0.0)
            # Trust score from -1 to 1, scale to adjust probability
            coop_prob = coop_rate * 0.7 + (0.5 + trust_score * 0.3)
            # Clamp
            coop_prob = max(0.0, min(1.0, coop_prob))
        # Adaptive threshold based on recent own success
        if self.recent_scores:
            avg = sum(self.recent_scores[-10:]) / len(self.recent_scores[-10:])
            # If we're doing well, be more cooperative; if poorly, more defecting
            self.threshold = 0.3 + avg * 0.2  # avg payoff ~1.5 -> threshold ~0.6
        else:
            self.threshold = 0.3
        # Decide: cooperate if probability exceeds threshold
        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own actions
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
            # Update recent scores based on what we did and opponent's action
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.recent_scores.append(3)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.recent_scores.append(0)
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.recent_scores.append(5)
            else:  # both defect
                self.recent_scores.append(1)
            # Keep last 30
            if len(self.recent_scores) > 30:
                self.recent_scores = self.recent_scores[-30:]
        if recipient_id == self.agent_id:
            # Also update recent scores if we are recipient? Actually we already did above if we are donor.
            # But if we are recipient and not donor, we observe our own action as recipient? The call has donor_action and recipient_action; we need to know our action.
            # Actually when we are recipient, our action is recipient_action. Update own counts too.
            if recipient_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
            # But we already added scores when we were donor? This could double count. Let's handle carefully.
            # The framework calls observe for each joint action seen by all agents, including the players themselves.
            # So if we are donor, we get one call; if we are recipient, we also get a call (same joint action). To avoid double counting, we should only update scores when we are donor.
            # So for recipient, we just update reputation/trust, not scores.
            pass

        # Update reputation for donor and recipient if they are not us (but we can also update for self? self doesn't need)
        if donor_id != self.agent_id:
            rep = self.reputations.setdefault(donor_id, {'c': 0, 'd': 0, 'n': 0})
            rep['n'] += 1
            if donor_action == 'cooperate':
                rep['c'] += 1
            else:
                rep['d'] += 1
        if recipient_id != self.agent_id:
            rep = self.reputations.setdefault(recipient_id, {'c': 0, 'd': 0, 'n': 0})
            rep['n'] += 1
            if recipient_action == 'cooperate':
                rep['c'] += 1
            else:
                rep['d'] += 1

        # Update trust based on observed behavior
        # If we are donor, we know our own action, but we can still judge opponent's action
        if donor_id == self.agent_id:
            # Opponent is recipient
            opp = recipient_id
            if recipient_action == 'cooperate':
                # They cooperated with us
                self.trust[opp] = self.trust.get(opp, 0.0) + 0.1
            else:
                self.trust[opp] = self.trust.get(opp, 0.0) - 0.2
        elif recipient_id == self.agent_id:
            # Opponent is donor
            opp = donor_id
            if donor_action == 'cooperate':
                self.trust[opp] = self.trust.get(opp, 0.0) + 0.1
            else:
                self.trust[opp] = self.trust.get(opp, 0.0) - 0.2
        else:
            # Third party: if both cooperate, both get positive; if one defects, that one gets negative
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) + 0.05
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) + 0.05
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) - 0.15
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) + 0.05
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) + 0.05
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) - 0.15
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) - 0.1
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) - 0.1

