class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.generation = 0
        self.round = 0
        self.total_rounds = 0
        self.scores = {}
        self.reputation = {}
        self.coop_count = 0
        self.defect_count = 0
        self.total_actions = 0
        self.opponent_history = {}
        self.self_history = []
        self.last_opponent = None
        self.memory = {}
        self.trust = {}
        self.epsilon = 0.05
        self.alpha = 0.2
        self.gamma = 0.9
        self.payoff_matrix = {
            ('cooperate', 'cooperate'): (3, 3),
            ('cooperate', 'defect'): (0, 5),
            ('defect', 'cooperate'): (5, 0),
            ('defect', 'defect'): (1, 1)
        }

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Initialize trust for new opponents
        if opponent not in self.trust:
            self.trust[opponent] = 0.5
        if opponent not in self.opponent_history:
            self.opponent_history[opponent] = []

        # Get opponent's cooperation rate
        history = self.opponent_history[opponent]
        if len(history) > 0:
            coop_rate = sum(1 for a in history if a == 'cooperate') / len(history)
        else:
            coop_rate = 0.5

        # Reputation-based adjustment
        rep = self.reputation.get(opponent, 0.5)

        # Combine signals
        trust_score = 0.4 * coop_rate + 0.3 * rep + 0.3 * self.trust[opponent]

        # Exploration with decreasing epsilon
        current_epsilon = self.epsilon * (0.95 ** self.generation)
        if random.random() < current_epsilon:
            return random.random() < 0.5

        # Deterministic strategy based on trust
        if trust_score > 0.6:
            return True
        elif trust_score < 0.4:
            return False
        else:
            # Tit-for-tat with forgiveness
            if len(history) > 0:
                last_opp_action = history[-1]
                if last_opp_action == 'defect':
                    # Forgive with small probability
                    return random.random() > 0.15
                else:
                    return True
            else:
                return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        self.total_rounds += 1
        self.round += 1
        if self.round > 30:
            self.round = 1
            self.generation += 1

        # Update reputation for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id != self.agent_id:
                if agent_id not in self.reputation:
                    self.reputation[agent_id] = 0.5
                # Reputation update: cooperate good, defect bad
                if action == 'cooperate':
                    self.reputation[agent_id] += 0.05
                else:
                    self.reputation[agent_id] -= 0.05
                self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

        # Update self action counts
        if donor_id == self.agent_id:
            self.total_actions += 1
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            self.self_history.append(donor_action)

        if recipient_id == self.agent_id:
            self.total_actions += 1
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            self.self_history.append(recipient_action)

        # Update opponent history when we are involved
        if donor_id == self.agent_id:
            opp = recipient_id
            opp_action = recipient_action
            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(opp_action)
            # Update trust based on outcome
            my_action = donor_action
            outcome = (my_action, opp_action)
            payoff = self.payoff_matrix[outcome][0]
            # Update trust: cooperation rewarded, defection punished
            if opp_action == 'cooperate':
                self.trust[opp] += 0.1
            else:
                self.trust[opp] -= 0.15
            self.trust[opp] = max(0.0, min(1.0, self.trust[opp]))

        if recipient_id == self.agent_id:
            opp = donor_id
            opp_action = donor_action
            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(opp_action)
            my_action = recipient_action
            outcome = (my_action, opp_action)
            payoff = self.payoff_matrix[outcome][1]
            if opp_action == 'cooperate':
                self.trust[opp] += 0.1
            else:
                self.trust[opp] -= 0.15
            self.trust[opp] = max(0.0, min(1.0, self.trust[opp]))

        # Third-party observations: track cooperation patterns
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Learn about both agents' behaviors
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.memory:
                    self.memory[agent_id] = []
                self.memory[agent_id].append(action)
                if len(self.memory[agent_id]) > 100:
                    self.memory[agent_id].pop(0)

            # Update trust based on observed interactions
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                # Mutual cooperation is good
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) + 0.02
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) + 0.02
            elif donor_action == 'defect' and recipient_action == 'defect':
                # Mutual defection is bad
                self.trust[donor_id] = self.trust.get(donor_id, 0.5) - 0.02
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.5) - 0.02
            else:
                # One cooperates, one defects: the defector is bad
                defector = donor_id if donor_action == 'defect' else recipient_id
                cooperator = donor_id if donor_action == 'cooperate' else recipient_id
                self.trust[defector] = self.trust.get(defector, 0.5) - 0.05
                self.trust[cooperator] = self.trust.get(cooperator, 0.5) + 0.01

            # Clamp trust values
            for agent in [donor_id, recipient_id]:
                self.trust[agent] = max(0.0, min(1.0, self.trust.get(agent, 0.5)))

