                self.my_coop_count += 1
            else:
                self.my_defect_count += 1

            if my_action == 'cooperate' and opp_action == 'defect':
                self.coop_threshold -= self.alpha
            elif my_action == 'defect' and opp_action == 'cooperate':
                self.coop_threshold += self.alpha * 0.5
            self.coop_threshold = max(0.1, min(0.9, self.coop_threshold))

        # New change: if we observe a third-party agent defecting against a cooperator, slightly reduce their reputation
        # This makes the agent more cautious about cooperating with those who defect against cooperative individuals
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect' and recipient_action == 'cooperate':
                if donor_id not in self.reputation:
                    self.reputation[donor_id] = [0, 0]
                self.reputation[donor_id][1] += 1  # extra defect count

