import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.trust = {}
        self.own_coop = 0
        self.own_defect = 0
        self.recent_scores = []
        self.coop_recent = 0
        self.defect_recent = 0
        self.threshold = 0.3
        self.rounds = 0
        self.gen = 0
        # New: track forgiveness level and cooperation history
        self.forgiveness = 0.3
        self.cooperation_history = {}

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None or opponent == self.agent_id:
            return True
        rep = self.reputations.get(opponent, {'c': 0, 'd': 0, 'n': 0})
        n = rep['n']
        if n == 0:
            coop_prob = 0.5
        else:
            coop_rate = rep['c'] / n
            trust_score = self.trust.get(opponent, 0.0)
            # Add forgiveness factor: if opponent has defected, give them a chance to redeem
            if rep['d'] > 0 and coop_rate > 0.3:
                coop_prob = coop_rate * 0.7 + (0.5 + trust_score * 0.3) + self.forgiveness * 0.1
            else:
                coop_prob = coop_rate * 0.7 + (0.5 + trust_score * 0.3)
            coop_prob = max(0.0, min(1.0, coop_prob))
        if self.recent_scores:
            avg = sum(self.recent_scores[-10:]) / len(self.recent_scores[-10:])
            self.threshold = 0.3 + avg * 0.2
        else:
            self.threshold = 0.3
        return random.random() < coop_prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.recent_scores.append(3)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.recent_scores.append(0)
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.recent_scores.append(5)
            else:
                self.recent_scores.append(1)
            if len(self.recent_scores) > 30:
                self.recent_scores = self.recent_scores[-30:]
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.own_coop += 1
            else:
                self.own_defect += 1

        if donor_id != self.agent_id:
            rep = self.reputations.setdefault(donor_id, {'c': 0, 'd': 0, 'n': 0})
            rep['n'] += 1
            if donor_action == 'cooperate':
                rep['c'] += 1
            else:
                rep['d'] += 1
        if recipient_id != self.agent_id:
            rep = self.reputations.setdefault(recipient_id, {'c': 0, 'd': 0, 'n': 0})
            rep['n'] += 1
            if recipient_action == 'cooperate':
                rep['c'] += 1
            else:
                rep['d'] += 1

        # New: Update cooperation history for forgiveness
        if donor_id != self.agent_id or recipient_id != self.agent_id:
            for agent_id in [donor_id, recipient_id]:
                if agent_id != self.agent_id:
                    hist = self.cooperation_history.setdefault(agent_id, [])
                    if donor_id == agent_id:
                        hist.append(1 if donor_action == 'cooperate' else 0)
                    else:
                        hist.append(1 if recipient_action == 'cooperate' else 0)
                    if len(hist) > 10:
                        hist = hist[-10:]
                    self.cooperation_history[agent_id] = hist

        if donor_id == self.agent_id:
            opp = recipient_id
            if recipient_action == 'cooperate':
                self.trust[opp] = self.trust.get(opp, 0.0) + 0.1
            else:
                self.trust[opp] = self.trust.get(opp, 0.0) - 0.2
        elif recipient_id == self.agent_id:
            opp = donor_id
            if donor_action == 'cooperate':
                self.trust[opp] = self.trust.get(opp, 0.0) + 0.1
            else:
                self.trust[opp] = self.trust.get(opp, 0.0) - 0.2
        else:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) + 0.05
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) + 0.05
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) - 0.15
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) + 0.05
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) + 0.05
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) - 0.15
            else:
                self.trust[donor_id] = self.trust.get(donor_id, 0.0) - 0.1
                self.trust[recipient_id] = self.trust.get(recipient_id, 0.0) - 0.1

        # New: Adjust forgiveness based on recent cooperation rate
        if self.own_coop + self.own_defect > 0:
            own_rate = self.own_coop / (self.own_coop + self.own_defect)
            if own_rate > 0.6:
                self.forgiveness = min(0.5, self.forgiveness + 0.01)
            else:
                self.forgiveness = max(0.1, self.forgiveness - 0.01)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.interaction_stats = {}
        self.self_actions = []
        self.base_coop_prob = 0.7
        self.recent_outcomes = []
        self.observed_count = 0
        # Track opponent's response to our cooperation/defection
        self.opp_response_after_my_coop = {}  # opponent_id -> [cooperation counts, defection counts]
        self.opp_response_after_my_defect = {}  # opponent_id -> [cooperation counts, defection counts]
        # New: track third-party impressions of each agent's cooperation rate
        self.third_party_coop = {}  # agent_id -> [coop, defect]
        self.generosity_bias = 0.1  # new parameter

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        # Adjust based on opponent's behavior after our actions
        prob = self.base_coop_prob
        # If opponent cooperates often after we cooperate, increase cooperation
        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob += (coop_rate_after - 0.5) * 0.5
        # If opponent cooperates often after we defect, we might exploit more
        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.3  # Slight decrease if they cooperate (we can exploit)

        prob += (opp_coop_rate - 0.5) * 0.4

        # New: incorporate third-party reputation
        if opponent_id in self.third_party_coop:
            tp_coop, tp_defect = self.third_party_coop[opponent_id]
            tp_total = tp_coop + tp_defect
            if tp_total > 0:
                tp_coop_rate = tp_coop / tp_total
                prob += (tp_coop_rate - 0.5) * self.generosity_bias

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        # New: update third-party reputation for all observed actions
        # Even if we are a participant, we still observe (but we'll handle self separately)
        if donor_id != self.agent_id:
            self.third_party_coop[donor_id] = self.third_party_coop.get(donor_id, [0, 0])
            if donor_action == 'cooperate':
                self.third_party_coop[donor_id][0] += 1
            else:
                self.third_party_coop[donor_id][1] += 1
        if recipient_id != self.agent_id:
            self.third_party_coop[recipient_id] = self.third_party_coop.get(recipient_id, [0, 0])
            if recipient_action == 'cooperate':
                self.third_party_coop[recipient_id][0] += 1
            else:
                self.third_party_coop[recipient_id][1] += 1

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent_id = donor_id
                my_action = recipient_action
                opp_action = donor_action
            key = my_action[0].upper() + opp_action[0].upper()
            stats = self.interaction_stats.setdefault(opponent_id, {})
            stats[key] = stats.get(key, 0) + 1
            self.self_actions.append((opponent_id, my_action, opp_action))

            # Track opponent's response after our actions
            if my_action == 'cooperate':
                if opponent_id not in self.opp_response_after_my_coop:
                    self.opp_response_after_my_coop[opponent_id] = [0, 0]
                if opp_action == 'cooperate':
                    self.opp_response_after_my_coop[opponent_id][0] += 1
                else:
                    self.opp_response_after_my_coop[opponent_id][1] += 1
            else:  # my_action == 'defect'
                if opponent_id not in self.opp_response_after_my_defect:
                    self.opp_response_after_my_defect[opponent_id] = [0, 0]
                if opp_action == 'cooperate':
                    self.opp_response_after_my_defect[opponent_id][0] += 1
                else:
                    self.opp_response_after_my_defect[opponent_id][1] += 1

            if my_action == 'cooperate' and opp_action == 'cooperate':
                payoff = 3
            elif my_action == 'cooperate' and opp_action == 'defect':
                payoff = 0
            elif my_action == 'defect' and opp_action == 'cooperate':
                payoff = 5
            else:
                payoff = 1
            self.recent_outcomes.append(payoff)
            if len(self.recent_outcomes) > 20:
                self.recent_outcomes.pop(0)
            if len(self.recent_outcomes) >= 5:
                avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
                if avg_payoff > 3.0:
                    self.base_coop_prob = min(0.95, self.base_coop_prob + 0.01)
                elif avg_payoff < 2.0:
                    self.base_coop_prob = max(0.05, self.base_coop_prob - 0.01)
        else:
            self.observed_count += 1

