        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        # New: update reputation for both donor and recipient based on this observation
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            coop_val = 1.0 if action == 'cooperate' else 0.0
            if agent_id in self.reputation_scores:
                self.reputation_scores[agent_id] = self.reputation_scores[agent_id] * 0.9 + coop_val * 0.1
            else:
                self.reputation_scores[agent_id] = coop_val

