        self.opponent_recent_outcomes = {}
        self.opp_donor_coop_rate = {}
        self.opp_specific_coop_rate = {}
        # New: Track both donor and recipient behavior for each opponent
        self.opp_behavior = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

