        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        if total == 0:
            opp_coop_rate = 0.5
        else:
            opp_coop_rate = coop / total

        stats = self.interaction_stats.get(opponent_id, {})
        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        if hist_total > 0:
            opp_defect_when_coop = cd / (cc + cd + 1e-9) if (cc+cd) > 0 else 0
        else:
            opp_defect_when_coop = 0

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8

        donor_stats = self.opp_donor_coop_rate.get(opponent_id, [0, 0])
        if donor_stats[1] > 0:
            donor_coop_rate = donor_stats[0] / donor_stats[1]
            prob += (donor_coop_rate - 0.5) * 0.4

        recent = self.opponent_recent_outcomes.get(opponent_id, [])
        if len(recent) >= 3:
            avg = sum(recent) / len(recent)
            if avg < 1.5:
                prob -= 0.15
            elif avg > 3.5:
                prob += 0.1

        # Mutation: Add a penalty for opponents who defect often when they are the donor
        # Use the donor-specific defect rate directly to reduce cooperation prob.
        if donor_stats[1] > 0:
            donor_defect_rate = 1 - donor_stats[0] / donor_stats[1]
            prob -= donor_defect_rate * 0.3

        # New mutation: Also consider the opponent's cooperation rate when they are the recipient
        # If they tend to cooperate as recipient, cooperate a bit more; if they defect, cooperate less.
        recipient_stats = self.opp_specific_coop_rate.get(opponent_id, [0, 0])
        if recipient_stats[1] > 0:
            recipient_coop_rate = recipient_stats[0] / recipient_stats[1]
