        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        if hist_total > 0:
            opp_defect_when_coop = cd / (cc + cd + 1e-9) if (cc+cd) > 0 else 0
        else:
