        prob += (opp_coop_rate - 0.5) * 0.4
        prob -= opp_defect_when_coop * 0.5
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += recent_factor
        prob += obs_factor
        prob += trend_factor
