        self.trust_decay = {}
        self.betrayal_count = {}
        self.recent_opp_coop = {}
        self.recent_observed = {}
        # NEW: Track the number of times this agent has been the donor in observed interactions
        self.donor_roles = {}
        # NEW: Track the average cooperation rate of each agent over all observations (global reputation)
        self.global_rep = {}
        # NEW: Track a "trustworthiness" score based on consistency of observed behavior
        self.consistency = {}
        # NEW: Track recent interactions with each opponent to detect patterns
        self.pattern_tracker = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
