        self.recent_defections = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        stats = self.interaction_stats.get(opponent_id, {})
        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        opp_defect_when_coop = 0
        if (cc + cd) > 0:
            opp_defect_when_coop = cd / (cc + cd)

        rep_score = self.reputation_scores.get(opponent_id, 0)
        rep_factor = max(-0.5, min(0.5, rep_score / 20.0))

        forgive = self.forgiveness.get(opponent_id, 0)
        forgive_factor = max(0, min(0.3, forgive * 0.05))

        decay = self.trust_decay.get(opponent_id, 0)
        decay_factor = max(-0.4, min(0.0, -decay * 0.02))

        betrayals = self.betrayal_count.get(opponent_id, 0)
        betrayal_factor = max(-0.3, min(0.0, -betrayals * 0.05))

        recent_list = self.recent_opp_coop.get(opponent_id, [])
        if recent_list:
            recent_coop_rate = sum(recent_list) / len(recent_list)
            recent_factor = (recent_coop_rate - 0.5) * 0.8
        else:
            recent_factor = 0.0

        observed = self.recent_observed.get(opponent_id, {'coop': 0, 'defect': 0})
        obs_total = observed['coop'] + observed['defect']
        if obs_total > 0:
            obs_coop_rate = observed['coop'] / obs_total
            obs_factor = (obs_coop_rate - 0.5) * 0.4
        else:
            obs_factor = 0.0

        # NEW: Add a factor based on recent third-party defections (within last 5 observations)
        recent_def_list = self.recent_defections.get(opponent_id, [])
        if len(recent_def_list) >= 2:
            recent_def_rate = sum(recent_def_list) / len(recent_def_list)
            def_factor = -recent_def_rate * 0.3
        else:
            def_factor = 0.0

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.4
        prob -= opp_defect_when_coop * 0.5
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += recent_factor
        prob += obs_factor
        prob += def_factor
        prob = max(0.05, min(0.95, prob))

