            elif pattern == 'alternating':
                # If alternating, use reciprocity
                prob += (self.reciprocity_index - 0.5) * 0.2

        # Add strategy classification adjustment
        strategy = self.opponent_strategy_classification.get(opponent_id, 'unknown')
        if strategy == 'tit_for_tat':
