    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.reputation_scores.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current + 0.01
        else:
            new = current - 0.02
        self.reputation_scores[agent_id] = max(0.0, min(1.0, new))

    def _update_punishment_and_forgiveness(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Punish defectors more when they defect against cooperators
        if donor_action == 'defect' and recipient_action == 'cooperate':
            self.punishment_scores[donor_id] = min(1.0, self.punishment_scores.get(donor_id, 0.0) + 0.1)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            # Forgive those who defect after being defected upon
            self.punishment_scores[donor_id] = max(0.0, self.punishment_scores.get(donor_id, 0.0) - 0.05)
        elif donor_action == 'cooperate' and recipient_action == 'cooperate':
            # Reduce punishment for mutual cooperation
            self.punishment_scores[donor_id] = max(0.0, self.punishment_scores.get(donor_id, 0.0) - 0.02)
            self.punishment_scores[recipient_id] = max(0.0, self.punishment_scores.get(recipient_id, 0.0) - 0.02)

        # Update forgiveness based on recent behavior
        if donor_action == 'cooperate':
            self.forgiveness_scores[donor_id] = min(1.0, self.forgiveness_scores.get(donor_id, 0.5) + 0.02)
        else:
            self.forgiveness_scores[donor_id] = max(0.0, self.forgiveness_scores.get(donor_id, 0.5) - 0.03)
        if recipient_action == 'cooperate':
