        mutual_factor = min(0.3, mutual * 0.02)

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor

        opp_prob = self.opponent_coop_probs.get(opponent_id, 0.5)
        prob += (opp_prob - 0.5) * 0.3

        volatility = self.opponent_volatility.get(opponent_id, 0.0)
        prob -= volatility * 0.2
        prob += (1.0 - volatility) * 0.05

        # New: incorporate reciprocity and altruism estimates
        reciprocity = self.opponent_reciprocity.get(opponent_id, 0.0)
        altruism = self.opponent_altruism.get(opponent_id, 0.0)
        # If opponent reciprocates cooperation, cooperate more
        prob += reciprocity * 0.3
        # If opponent is altruistic (cooperates even when not reciprocated), cooperate more
        prob += altruism * 0.2

        # New: adjust based on global cooperation rate to adapt to environment
        # If the environment is generally cooperative, be slightly more cooperative; if defection is common, be more cautious
        prob += (self.global_coop_rate - 0.5) * 0.1

        prob = max(0.05, min(0.95, prob))

