                avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
                if avg_payoff > 3.0:
                    self.base_coop_prob = min(0.95, self.base_coop_prob + 0.01)
                elif avg_payoff < 2.0:
                    self.base_coop_prob = max(0.05, self.base_coop_prob - 0.01)
            opp_coop = self.coop_counts.get(opponent_id, 0)
            opp_def = self.defect_counts.get(opponent_id, 0)
            opp_total = opp_coop + opp_def
            if opp_total > 0:
                self.opponent_coop_probs[opponent_id] = opp_coop / opp_total
            if opponent_id not in self.opponent_volatility:
                self.opponent_volatility[opponent_id] = 0.0
            if self.self_actions:
