                self.trust_decay[recipient_id] = self.trust_decay.get(recipient_id, 0) + 0.5
            self.observed_count += 1
            self._track_third_party(donor_id, donor_action, recipient_id, recipient_action)
            # New: also update reciprocity/altruism estimates from third-party observations
            self._update_reciprocity_altruism_third_party(donor_id, donor_action, recipient_id, recipient_action)

    def _update_reciprocity_altruism(self, opponent_id: int, my_action: str, opp_action: str) -> None:
        if opponent_id not in self.opponent_reciprocity:
            self.opponent_reciprocity[opponent_id] = 0.0
        if opponent_id not in self.opponent_altruism:
            self.opponent_altruism[opponent_id] = 0.0
        # Reciprocity: if I cooperate and opponent cooperates, increase; if I cooperate and opponent defects, decrease
        if my_action == 'cooperate' and opp_action == 'cooperate':
            self.opponent_reciprocity[opponent_id] = min(1.0, self.opponent_reciprocity.get(opponent_id, 0.0) + 0.1)
        elif my_action == 'cooperate' and opp_action == 'defect':
            self.opponent_reciprocity[opponent_id] = max(0.0, self.opponent_reciprocity.get(opponent_id, 0.0) - 0.1)
        # Altruism: if opponent cooperates when I defect, increase; if opponent defects when I defect, decrease
        if my_action == 'defect' and opp_action == 'cooperate':
            self.opponent_altruism[opponent_id] = min(1.0, self.opponent_altruism.get(opponent_id, 0.0) + 0.1)
        elif my_action == 'defect' and opp_action == 'defect':
            self.opponent_altruism[opponent_id] = max(0.0, self.opponent_altruism.get(opponent_id, 0.0) - 0.05)

    def _update_reciprocity_altruism_third_party(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # For third-party observations, infer reciprocity/altruism from the pair's behavior
        # If donor and recipient both cooperate, they likely reciprocate
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            if donor_id not in self.opponent_reciprocity:
                self.opponent_reciprocity[donor_id] = 0.0
            if recipient_id not in self.opponent_reciprocity:
                self.opponent_reciprocity[recipient_id] = 0.0
            self.opponent_reciprocity[donor_id] = min(1.0, self.opponent_reciprocity.get(donor_id, 0.0) + 0.02)
            self.opponent_reciprocity[recipient_id] = min(1.0, self.opponent_reciprocity.get(recipient_id, 0.0) + 0.02)
        # If donor defects but recipient cooperates, donor is not reciprocating, recipient might be altruistic
        if donor_action == 'defect' and recipient_action == 'cooperate':
            if recipient_id not in self.opponent_altruism:
                self.opponent_altruism[recipient_id] = 0.0
            self.opponent_altruism[recipient_id] = min(1.0, self.opponent_altruism.get(recipient_id, 0.0) + 0.02)
            if donor_id not in self.opponent_reciprocity:
                self.opponent_reciprocity[donor_id] = 0.0
            self.opponent_reciprocity[donor_id] = max(0.0, self.opponent_reciprocity.get(donor_id, 0.0) - 0.02)

    def _track_third_party(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        pair_key = (donor_id, recipient_id)
        record = self.third_party_records.setdefault(pair_key, {'coop': 0, 'defect': 0, 'count': 0})
        if donor_action == 'cooperate':
            record['coop'] += 1
        else:
            record['defect'] += 1
        if recipient_action == 'cooperate':
            record['coop'] += 1
        else:
            record['defect'] += 1
        record['count'] += 2

        if record['count'] % 10 == 0:
            coop_rate = record['coop'] / record['count']
            if coop_rate < 0.4:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.005)
            elif coop_rate > 0.6:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.005)

