        recent_flags = self.recent_opponent_coop_flags.get(opponent_id, [])
        if recent_flags:
            recent_rate = sum(recent_flags) / len(recent_flags)
            # If recent cooperation is high, cooperate more; if low, be cautious
            prob += (recent_rate - 0.5) * 0.2

        prob += (self.global_coop_rate - 0.5) * 0.1

        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

