                self.recent_opponent_actions[opponent_id].pop(0)

            if my_action == 'cooperate':
                if opponent_id not in self.opp_response_after_my_coop:
                    self.opp_response_after_my_coop[opponent_id] = [0, 0]
                if opp_action == 'cooperate':
