    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        trust = self.trust_scores.get(opponent_id, 0.5)
        reputation = self.reputation_scores.get(opponent_id, 0.5)
        punishment = self.punishment_scores.get(opponent_id, 0.0)
        forgiveness = self.forgiveness_scores.get(opponent_id, 0.5)

        recent_actions = self.recent_opponent_actions.get(opponent_id, [])
        if len(recent_actions) >= 3:
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.reciprocity_index = coop_count / len(recent_actions)
        else:
            self.reciprocity_index = 0.5

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.3
        prob += (trust - 0.5) * 0.2
        prob += (reputation - 0.5) * 0.1
        prob -= punishment * 0.3
        prob += (forgiveness - 0.5) * 0.15
        prob += (self.reciprocity_index - 0.5) * 0.25

        defect_pen = self.defect_penalty.get(opponent_id, 0.0)
        coop_bonus = self.coop_bonus.get(opponent_id, 0.0)
        prob -= defect_pen * 0.2
        prob += coop_bonus * 0.2

        third_party_punish = self.third_party_punishment.get(opponent_id, 0.0)
        third_party_reward = self.third_party_reward.get(opponent_id, 0.0)
        prob -= third_party_punish * 0.25
        prob += third_party_reward * 0.25

        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob += (coop_rate_after - 0.5) * 0.4

        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.2

        if total >= 5:
            prob += (opp_coop_rate - 0.5) * 0.1

        if len(self.recent_outcomes) >= 5:
            avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_payoff > 2.8:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.02)
            elif avg_payoff < 2.2:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.02)

        emotional = self.emotional_memory.get(opponent_id, 0.0)
        prob += emotional * 0.1

        confidence = self.reputation_confidence.get(opponent_id, 0.5)
        prob += (confidence - 0.5) * 0.1

        # New: incorporate third-party observed cooperation rates
        third_party_rate = self.third_party_coop_rates.get(opponent_id, 0.5)
        prob += (third_party_rate - 0.5) * 0.15

        # New: incorporate third-party trust
        third_trust = self.third_party_trust.get(opponent_id, 0.5)
        prob += (third_trust - 0.5) * 0.1

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

