        else:
            self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.02)

    def _update_emotional_memory(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Track emotional valence of interactions: positive when cooperate-cooperate, negative when defect-defect
        if donor_id not in self.emotional_memory:
            self.emotional_memory[donor_id] = 0.0
        if recipient_id not in self.emotional_memory:
            self.emotional_memory[recipient_id] = 0.0

        if donor_action == 'cooperate' and recipient_action == 'cooperate':
