        if record['count'] % 10 == 0:
            coop_rate = record['coop'] / record['count']
            if coop_rate < 0.4:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.005)
            elif coop_rate > 0.6:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.005)

