        conform = self.social_conformity.get(opponent_id, 0.5)
        if conform > 0.5:
            # If opponent is easily influenced by others, be more cautious
            prob -= (conform - 0.5) * 0.1
        else:
            # If opponent is independent, trust them slightly more
            prob += (0.5 - conform) * 0.05

        # New: adjust based on opponent's behavioral consistency
