import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.interaction_stats = {}
        self.self_actions = []
        self.base_coop_prob = 0.7
        self.recent_outcomes = []
        self.observed_count = 0
        self.reputation_scores = {}
        self.forgiveness = {}
        self.trust_decay = {}
        self.betrayal_count = {}
        self.betrayal_streak = {}
        self.mutual_coop_count = {}
        self.third_party_records = {}
        self.opponent_coop_probs = {}
        self.opponent_volatility = {}
        self.opponent_consistency = {}
        self.last_opponent_action = {}
        self.opponent_recent_actions = {}
        self.reciprocation_count = {}
        self.reciprocation_opportunities = {}
        # New: track opponent's defection frequency in recent interactions
        self.opponent_recent_defections = {}
        # New: track how many times we cooperated with this opponent
        self.my_coop_with_opponent = {}
        # New: track opponent's recent cooperation streak
        self.opponent_coop_streak = {}
        # New: track opponent's overall cooperativeness trend
        self.opponent_trend = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        stats = self.interaction_stats.get(opponent_id, {})
        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        opp_defect_when_coop = 0
        if (cc + cd) > 0:
            opp_defect_when_coop = cd / (cc + cd)

        rep_score = self.reputation_scores.get(opponent_id, 0)
        rep_factor = max(-0.5, min(0.5, rep_score / 20.0))

        forgive = self.forgiveness.get(opponent_id, 0)
        forgive_factor = max(0, min(0.3, forgive * 0.05))

        decay = self.trust_decay.get(opponent_id, 0)
        decay_factor = max(-0.4, min(0.0, -decay * 0.02))

        betrayals = self.betrayal_count.get(opponent_id, 0)
        betrayal_factor = max(-0.3, min(0.0, -betrayals * 0.05))

        streak = self.betrayal_streak.get(opponent_id, 0)
        streak_factor = max(-0.4, min(0.0, -streak * 0.1))

        mutual = self.mutual_coop_count.get(opponent_id, 0)
        mutual_factor = min(0.3, mutual * 0.02)

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor

        opp_prob = self.opponent_coop_probs.get(opponent_id, 0.5)
        prob += (opp_prob - 0.5) * 0.3

        volatility = self.opponent_volatility.get(opponent_id, 0.0)
        prob -= volatility * 0.2
        prob += (1.0 - volatility) * 0.05

        consistency = self.opponent_consistency.get(opponent_id, 0.5)
        if opp_coop_rate > 0.5:
            prob += (consistency - 0.5) * 0.2
        else:
            prob -= (consistency - 0.5) * 0.2

        recip_opp = self.reciprocation_opportunities.get(opponent_id, 0)
        recip_count = self.reciprocation_count.get(opponent_id, 0)
        recip_rate = recip_count / recip_opp if recip_opp > 0 else 0.5
        prob += (recip_rate - 0.5) * 0.3

        recent = self.opponent_recent_actions.get(opponent_id, [])
        if recent:
            last_action = recent[-1]
            if last_action == 'cooperate':
                prob += 0.1
            else:
                prob -= 0.1

        # New: incorporate recent defection frequency (if opponent defects often recently, lower prob)
        recent_def = self.opponent_recent_defections.get(opponent_id, 0)
        recent_total = len(recent)
        if recent_total > 0:
            recent_def_rate = recent_def / recent_total
            prob -= recent_def_rate * 0.2

        # New: if we cooperated many times with this opponent, increase trust
        my_coop = self.my_coop_with_opponent.get(opponent_id, 0)
        prob += min(0.2, my_coop * 0.01)

        # New: incorporate opponent's cooperation streak
        coop_streak = self.opponent_coop_streak.get(opponent_id, 0)
        if coop_streak > 2:
            prob += min(0.15, coop_streak * 0.02)
        elif coop_streak < -2:
            prob -= min(0.15, abs(coop_streak) * 0.02)

        # New: incorporate opponent's trend (recent cooperation rate vs overall)
        trend = self.opponent_trend.get(opponent_id, 0.0)
        prob += trend * 0.15

        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        self.reputation_scores[donor_id] = self.reputation_scores.get(donor_id, 0) + (1 if donor_action == 'cooperate' else -1)
        self.reputation_scores[recipient_id] = self.reputation_scores.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else -1)

        if donor_action == 'defect':
            self.trust_decay[donor_id] = self.trust_decay.get(donor_id, 0) + 1
        if recipient_action == 'defect':
            self.trust_decay[recipient_id] = self.trust_decay.get(recipient_id, 0) + 1

        if donor_id in self.interaction_stats and donor_action == 'cooperate':
            stats = self.interaction_stats[donor_id]
            dd = stats.get('DD', 0)
            dc = stats.get('DC', 0)
            if dd > 0 and dc > 0:
                self.forgiveness[donor_id] = self.forgiveness.get(donor_id, 0) + 1

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent_id = donor_id
                my_action = recipient_action
                opp_action = donor_action
            key = my_action[0].upper() + opp_action[0].upper()
            stats = self.interaction_stats.setdefault(opponent_id, {})
            stats[key] = stats.get(key, 0) + 1
            self.self_actions.append((opponent_id, my_action, opp_action))
            if my_action == 'cooperate' and opp_action == 'cooperate':
                self.mutual_coop_count[opponent_id] = self.mutual_coop_count.get(opponent_id, 0) + 1
            if opp_action == 'defect':
                self.betrayal_count[opponent_id] = self.betrayal_count.get(opponent_id, 0) + 1
                self.betrayal_streak[opponent_id] = self.betrayal_streak.get(opponent_id, 0) + 1
            else:
                self.betrayal_streak[opponent_id] = 0
            if my_action == 'cooperate' and opp_action == 'cooperate':
                payoff = 3
            elif my_action == 'cooperate' and opp_action == 'defect':
                payoff = 0
            elif my_action == 'defect' and opp_action == 'cooperate':
                payoff = 5
            else:
                payoff = 1
            self.recent_outcomes.append(payoff)
            if len(self.recent_outcomes) > 20:
                self.recent_outcomes.pop(0)
            if len(self.recent_outcomes) >= 5:
                avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
                if avg_payoff > 3.0:
                    self.base_coop_prob = min(0.95, self.base_coop_prob + 0.01)
                elif avg_payoff < 2.0:
                    self.base_coop_prob = max(0.05, self.base_coop_prob - 0.01)
            opp_coop = self.coop_counts.get(opponent_id, 0)
            opp_def = self.defect_counts.get(opponent_id, 0)
            opp_total = opp_coop + opp_def
            if opp_total > 0:
                self.opponent_coop_probs[opponent_id] = opp_coop / opp_total
            if opponent_id not in self.opponent_volatility:
                self.opponent_volatility[opponent_id] = 0.0
            if self.self_actions:
                prev_actions = [a for a in self.self_actions if a[0] == opponent_id]
                if len(prev_actions) >= 2:
                    last_action = prev_actions[-1][2]
                    current_action = opp_action
                    if last_action != current_action:
                        self.opponent_volatility[opponent_id] = min(1.0, self.opponent_volatility.get(opponent_id, 0.0) + 0.1)
                    else:
                        self.opponent_volatility[opponent_id] = max(0.0, self.opponent_volatility.get(opponent_id, 0.0) - 0.05)
            if opponent_id not in self.opponent_consistency:
                self.opponent_consistency[opponent_id] = 0.5
            if opponent_id in self.last_opponent_action:
                if self.last_opponent_action[opponent_id] == opp_action:
                    self.opponent_consistency[opponent_id] = min(1.0, self.opponent_consistency[opponent_id] + 0.1)
                else:
                    self.opponent_consistency[opponent_id] = max(0.0, self.opponent_consistency[opponent_id] - 0.1)
            self.last_opponent_action[opponent_id] = opp_action
            if opponent_id not in self.opponent_recent_actions:
                self.opponent_recent_actions[opponent_id] = []
            recent = self.opponent_recent_actions[opponent_id]
            recent.append(opp_action)
            if len(recent) > 5:
                recent.pop(0)
            # New: update recent defection count
            if opponent_id not in self.opponent_recent_defections:
                self.opponent_recent_defections[opponent_id] = 0
            if opp_action == 'defect':
                self.opponent_recent_defections[opponent_id] += 1
            if len(recent) > 5:
                # Remove the oldest from count if it was defect
                if recent[0] == 'defect':
                    self.opponent_recent_defections[opponent_id] = max(0, self.opponent_recent_defections[opponent_id] - 1)

            # New: track our cooperation with this opponent
            if my_action == 'cooperate':
                self.my_coop_with_opponent[opponent_id] = self.my_coop_with_opponent.get(opponent_id, 0) + 1

            if my_action == 'cooperate' and opp_action == 'cooperate':
                self.reciprocation_count[opponent_id] = self.reciprocation_count.get(opponent_id, 0) + 1
                self.reciprocation_opportunities[opponent_id] = self.reciprocation_opportunities.get(opponent_id, 0) + 1
            elif my_action == 'cooperate' and opp_action == 'defect':
                self.reciprocation_opportunities[opponent_id] = self.reciprocation_opportunities.get(opponent_id, 0) + 1

            # New: update cooperation streak for opponent
            if opp_action == 'cooperate':
                self.opponent_coop_streak[opponent_id] = self.opponent_coop_streak.get(opponent_id, 0) + 1
            else:
                self.opponent_coop_streak[opponent_id] = self.opponent_coop_streak.get(opponent_id, 0) - 1

