        else:
            self.forgiveness_scores[recipient_id] = max(0.0, self.forgiveness_scores.get(recipient_id, 0.5) - 0.03)

    def _update_third_party_trust(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
