        observed_freq_factor = (observed_freq - 0.5) * 0.15

        # New: punish agents that defect against others (third-party punishment)
        punish_count = self.punishment_count.get(opponent_id, 0)
        punish_factor = max(-0.25, min(0.0, -punish_count * 0.08))

