        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        opp_defect_when_coop = 0
        if (cc + cd) > 0:
            opp_defect_when_coop = cd / (cc + cd)

        rep_score = self.reputation_scores.get(opponent_id, 0)
        rep_factor = max(-0.5, min(0.5, rep_score / 20.0))

        forgive = self.forgiveness.get(opponent_id, 0)
        forgive_factor = max(0, min(0.3, forgive * 0.05))

        decay = self.trust_decay.get(opponent_id, 0)
        decay_factor = max(-0.4, min(0.0, -decay * 0.02))

        betrayals = self.betrayal_count.get(opponent_id, 0)
        betrayal_factor = max(-0.3, min(0.0, -betrayals * 0.05))

        streak = self.betrayal_streak.get(opponent_id, 0)
        streak_factor = max(-0.4, min(0.0, -streak * 0.1))

        mutual = self.mutual_coop_count.get(opponent_id, 0)
        mutual_factor = min(0.3, mutual * 0.02)

        recent_coop = self.opponent_recent_coop.get(opponent_id, [])
        recent_avg = sum(recent_coop) / len(recent_coop) if recent_coop else 0.5
        recent_factor = (recent_avg - 0.5) * 0.2

        history = self.opponent_action_history.get(opponent_id, [])
        pattern_factor = 0.0
        if len(history) >= 3:
            coop_after_my_coop = 0
            coop_after_my_coop_total = 0
            for i in range(len(history)-1):
                if history[i][0] == 'cooperate':
                    coop_after_my_coop_total += 1
                    if history[i+1][1] == 'cooperate':
                        coop_after_my_coop += 1
            if coop_after_my_coop_total > 0:
                ratio = coop_after_my_coop / coop_after_my_coop_total
                pattern_factor = (ratio - 0.5) * 0.15

        recent_rate = self.recent_coop_rate.get(opponent_id, 0.5)
        recent_rate_factor = (recent_rate - 0.5) * 0.1

