                self.recent_outcomes.pop(0)
        else:
            self.observed_count += 1

    def _update_trust(self, agent_id: int, action: str) -> None:
        current = self.trust_scores.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current + 0.02
        else:
            new = current - 0.03
        self.trust_scores[agent_id] = max(0.0, min(1.0, new))

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.reputation_scores.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current + 0.01
        else:
            new = current - 0.02
        self.reputation_scores[agent_id] = max(0.0, min(1.0, new))

    def _update_punishment_and_forgiveness(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'defect' and recipient_action == 'cooperate':
            self.punishment_scores[donor_id] = min(1.0, self.punishment_scores.get(donor_id, 0.0) + 0.1)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            self.punishment_scores[donor_id] = max(0.0, self.punishment_scores.get(donor_id, 0.0) - 0.05)
        elif donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.punishment_scores[donor_id] = max(0.0, self.punishment_scores.get(donor_id, 0.0) - 0.02)
            self.punishment_scores[recipient_id] = max(0.0, self.punishment_scores.get(recipient_id, 0.0) - 0.02)

        if donor_action == 'cooperate':
            self.forgiveness_scores[donor_id] = min(1.0, self.forgiveness_scores.get(donor_id, 0.5) + 0.02)
        else:
            self.forgiveness_scores[donor_id] = max(0.0, self.forgiveness_scores.get(donor_id, 0.5) - 0.03)
        if recipient_action == 'cooperate':
            self.forgiveness_scores[recipient_id] = min(1.0, self.forgiveness_scores.get(recipient_id, 0.5) + 0.02)
        else:
            self.forgiveness_scores[recipient_id] = max(0.0, self.forgiveness_scores.get(recipient_id, 0.5) - 0.03)

    def _update_third_party_trust(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'cooperate':
            self.trust_scores[donor_id] = min(1.0, self.trust_scores.get(donor_id, 0.5) + 0.015)
        else:
            self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.02)
        if recipient_action == 'cooperate':
            self.trust_scores[recipient_id] = min(1.0, self.trust_scores.get(recipient_id, 0.5) + 0.015)
        else:
            self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.02)

    def _update_emotional_memory(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.emotional_memory:
            self.emotional_memory[donor_id] = 0.0
        if recipient_id not in self.emotional_memory:
            self.emotional_memory[recipient_id] = 0.0

        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.emotional_memory[donor_id] = min(1.0, self.emotional_memory[donor_id] + 0.1)
            self.emotional_memory[recipient_id] = min(1.0, self.emotional_memory[recipient_id] + 0.1)
        elif donor_action == 'defect' and recipient_action == 'defect':
            self.emotional_memory[donor_id] = max(-1.0, self.emotional_memory[donor_id] - 0.1)
            self.emotional_memory[recipient_id] = max(-1.0, self.emotional_memory[recipient_id] - 0.1)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
