            self.emotional_memory[recipient_id] = max(-1.0, self.emotional_memory[recipient_id] - 0.05)

    def _update_reputation_confidence(self, agent_id: int, action: str) -> None:
        current_rep = self.reputation_scores.get(agent_id, 0.5)
