        self.defect_penalty[agent_id] = max(0.0, min(1.0, new))

    def _update_coop_bonus(self, agent_id: int, action: str) -> None:
        current = self.coop_bonus.get(agent_id, 0.0)
        if action == 'cooperate':
            new = current + 0

