        punish = self.punishment_tendency.get(opponent_id, 0)
        punish_factor = max(-0.3, min(0.0, -punish * 0.1))
        prob += punish_factor

        # New: retaliation memory - if we punished and they retaliated, be more cautious
        retal = self.retaliation_memory.get(opponent_id, 0)
        retal_factor = max(-0.2, min(0.0, -retal * 0.05))
