                self.reciprocation_opportunities[opponent_id] = self.reciprocation_opportunities.get(opponent_id, 0) + 1

            # New: update response stats
            resp_stats = self.opponent_response_stats.setdefault(opponent_id, {'coop_after_coop': 0, 'coop_after_coop_total': 0})
            if my_action == 'cooperate':
                resp_stats['coop_after_coop_total'] += 1
