                trust_val = self.trust_by_action.get((opponent_id, trust_key), 0.5)
                if opp_action == 'cooperate':
                    trust_val = min(1.0, trust_val + 0.1)
                else:
                    trust_val = max(0.0, trust_val - 0.1)
