            elif my_action == 'cooperate' and opp_action == 'defect':
                payoff = 0
            elif my_action == 'defect' and opp_action == 'cooperate':
                payoff = 5
            else:
                payoff = 1
            self.recent_outcomes.append(payoff)
            if len(self.recent_outcomes) > 20:
                self.recent_outcomes.pop(0)
            if len(self.recent_outcomes) >= 5:
                avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
                if avg_payoff > 3.0:
                    self.base_coop_prob = min(0.95, self.base_coop_prob + 0.01)
                elif avg_payoff < 2.0:
                    self.base_coop_prob = max(0.05, self.base_coop_prob - 0.01)
            recent = self.opponent_recent_coop.setdefault(opponent_id, [])
            recent.append(1 if opp_action == 'cooperate' else 0)
            if len(recent) > 10:
                recent.pop(0)

            # New: track cooperation streak for opponent
            if opp_action == 'cooperate':
                self.coop_streak[opponent_id] = self.coop_streak.get(opponent_id, 0) + 1
            else:
                self.coop_streak[opponent_id] = 0
        else:
            if donor_action == 'defect':
                self.trust_decay[donor_id] = self.trust_decay.get(donor_id, 0) + 0.5
            if recipient_action == 'defect':
                self.trust_decay[recipient_id] = self.trust_decay.get(recipient_id, 0) + 0.5
            self.observed_count += 1
            self._track_third_party(donor_id, donor_action, recipient_id, recipient_action)

            # New: punish agents that defect against others
            if donor_action == 'defect' and donor_id != self.agent_id:
                self.punishment_count[donor_id] = self.punishment_count.get(donor_id, 0) + 1
                self.third_party_betrayal_count[donor_id] = self.third_party_betrayal_count.get(donor_id, 0) + 1
            if recipient_action == 'defect' and recipient_id != self.agent_id:
                self.punishment_count[recipient_id] = self.punishment_count.get(recipient_id, 0) + 1
                self.third_party_betrayal_count[recipient_id] = self.third_party_betrayal_count.get(recipient_id, 0) + 1

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            self.total_observed_actions[agent_id] = self.total_observed_actions.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.observed_coop_count[agent_id] = self.observed_coop_count.get(agent_id, 0) + 1

    def _track_third_party(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        pair_key = (donor_id, recipient_id)
        record = self.third_party_records.setdefault(pair_key, {'coop': 0, 'defect': 0, 'count': 0})
        if donor_action == 'cooperate':
            record['coop'] += 1
        else:
            record['defect'] += 1
        if recipient_action == 'cooperate':
            record['coop'] += 1
        else:
            record['defect'] += 1
        record['count'] += 2

        if record['count'] % 10 == 0:
            coop_rate = record['coop'] / record['count']
            if coop_rate < 0.4:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.005)
            elif coop_rate > 0.6:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.005)

        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            recent = self.recent_coop_rate.setdefault(agent_id, 0.5)
            self.recent_coop_rate[agent_id] = recent * 0.9 + (1 if action == 'cooperate' else 0) * 0.1

