        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        trust = self.trust_scores.get(opponent_id, 0.5)
        reputation = self.reputation_scores.get(opponent_id, 0.5)
        punishment = self.punishment_scores.get(opponent_id, 0.0)
        forgiveness = self.forgiveness_scores.get(opponent_id, 0.5)

        recent_actions = self.recent_opponent_actions.get(opponent_id, [])
        if len(recent_actions) >= 3:
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.reciprocity_index = coop_count / len(recent_actions)
        else:
            self.reciprocity_index = 0.5

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.3
        prob += (trust - 0.5) * 0.2
        prob += (reputation - 0.5) * 0.1
        prob -= punishment * 0.3
        prob += (forgiveness - 0.5) * 0.15
        prob += (self.reciprocity_index - 0.5) * 0.25

        defect_pen = self.defect_penalty.get(opponent_id, 0.0)
        coop_bonus = self.coop_bonus.get(opponent_id, 0.0)
        prob -= defect_pen * 0.2
        prob += coop_bonus * 0.2

        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob += (coop_rate_after - 0.5) * 0.4

        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.2

        third_party = self.third_party_observations.get(opponent_id, 0.0)
        prob += third_party * 0.15

        third_party_defects = self.third_party_defect_count.get(opponent_id, 0)
        if third_party_defects > 2:
            prob -= min(0.3, third_party_defects * 0.02)

        # New: Reward agents with high third-party cooperation rate
        third_party_coops = self.third_party_coop_count.get(opponent_id, 0)
        third_party_total = third_party_coops + third_party_defects
        if third_party_total > 2:
            third_party_coop_rate = third_party_coops / third_party_total
            prob += (third_party_coop_rate - 0.5) * 0.2

        if total >= 5:
            prob += (opp_coop_rate - 0.5) * 0.1

        if len(self.recent_outcomes) >= 5:
            avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_payoff > 2.8:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.02)
            elif avg_payoff < 2.2:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.02)

        emotional = self.emotional_memory.get(opponent_id, 0.0)
        prob += emotional * 0.1

        confidence = self.reputation_confidence.get(opponent_id, 0.5)
        prob += (confidence - 0.5) * 0.1

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        self._update_trust(donor_id, donor_action)
        self._update_trust(recipient_id, recipient_action)
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_punishment_and_forgiveness(donor_id, donor_action, recipient_id, recipient_action)

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_third_party_trust(donor_id, donor_action, recipient_id, recipient_action)
            self._update_third_party_patterns(donor_id, donor_action, recipient_id, recipient_action)
            if donor_action == 'defect':
                self.third_party_defect_count[donor_id] = self.third_party_defect_count.get(donor_id, 0) + 1
            else:
                # New: Count third-party cooperations
                self.third_party_coop_count[donor_id] = self.third_party_coop_count.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.third_party_defect_count[recipient_id] = self.third_party_defect_count.get(recipient_id, 0) + 1
            else:
                # New: Count third-party cooperations
                self.third_party_coop_count[recipient_id] = self.third_party_coop_count.get(recipient_id, 0) + 1

        self._update_emotional_memory(donor_id, donor_action, recipient_id, recipient_action)

        self._update_reputation_confidence(donor_id, donor_action)
        self._update_reputation_confidence(recipient_id, recipient_action)

        self._update_defect_penalty(donor_id, donor_action)
        self._update_defect_penalty(recipient_id, recipient_action)
        self._update_coop_bonus(donor_id, donor_action)
        self._update_coop_bonus(recipient_id, recipient_action)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent_id = donor_id
                my_action = recipient_action
                opp_action = donor_action
            key = my_action[0].upper() + opp_action[0].upper()
            stats = self.interaction_stats.setdefault(opponent_id, {})
            stats[key] = stats.get(key, 0) + 1
            self.self_actions.append((opponent_id, my_action, opp_action))

            if opponent_id not in self.recent_opponent_actions:
                self.recent_opponent_actions[opponent_id] = []
            self.recent_opponent_actions[opponent_id].append(opp_action)
            if len(self.recent_opponent_actions[opponent_id]) > 10:
                self.recent_opponent_actions[opponent_id].pop(0)

            if my_action == 'cooperate':
                if opponent_id not in self.opp_response_after_my_coop:
                    self.opp_response_after_my_coop[opponent_id] = [0, 0]
                if opp_action == 'cooperate':
                    self.opp_response_after_my_coop[opponent_id][0] += 1
                else:
                    self.opp_response_after_my_coop[opponent_id][1] += 1
            else:
                if opponent_id not in self.opp_response_after_my_defect:
                    self.opp_response_after_my_defect[opponent_id] = [0, 0]
                if opp_action == 'cooperate':
                    self.opp_response_after_my_defect[opponent_id][0] += 1
                else:
                    self.opp_response_after_my_defect[opponent_id][1] += 1

            if my_action == 'cooperate' and opp_action == 'cooperate':
                payoff = 3
            elif my_action == 'cooperate' and opp_action == 'defect':
                payoff = 0
            elif my_action == 'defect' and opp_action == 'cooperate':
                payoff = 5
            else:
                payoff = 1
            self.recent_outcomes.append(payoff)
            if len(self.recent_outcomes) > 20:
                self.recent_outcomes.pop(0)
        else:
            self.observed_count += 1

    def _update_trust(self, agent_id: int, action: str) -> None:
        current = self.trust_scores.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current + 0.02
        else:
            new = current - 0.03
        self.trust_scores[agent_id] = max(0.0, min(1.0, new))

    def _update_reputation(self, agent_id: int, action: str) -> None:
        current = self.reputation_scores.get(agent_id, 0.5)
        if action == 'cooperate':
            new = current + 0.01
        else:
            new = current - 0.02
        self.reputation_scores[agent_id] = max(0.0, min(1.0, new))

    def _update_punishment_and_forgiveness(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'defect' and recipient_action == 'cooperate':
            self.punishment_scores[donor_id] = min(1.0, self.punishment_scores.get(donor_id, 0.0) + 0.1)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            self.punishment_scores[donor_id] = max(0.0, self.punishment_scores.get(donor_id, 0.0) - 0.05)
        elif donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.punishment_scores[donor_id] = max(0.0, self.punishment_scores.get(donor_id, 0.0) - 0.02)
            self.punishment_scores[recipient_id] = max(0.0, self.punishment_scores.get(recipient_id, 0.0) - 0.02)

        if donor_action == 'cooperate':
            self.forgiveness_scores[donor_id] = min(1.0, self.forgiveness_scores.get(donor_id, 0.5) + 0.02)
        else:
            self.forgiveness_scores[donor_id] = max(0.0, self.forgiveness_scores.get(donor_id, 0.5) - 0.03)
        if recipient_action == 'cooperate':
            self.forgiveness_scores[recipient_id] = min(1.0, self.forgiveness_scores.get(recipient_id, 0.5) + 0.02)
        else:
            self.forgiveness_scores[recipient_id] = max(0.0, self.forgiveness_scores.get(recipient_id, 0.5) - 0.03)

    def _update_third_party_trust(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'cooperate':
            self.trust_scores[donor_id] = min(1.0, self.trust_scores.get(donor_id, 0.5) + 0.015)
        else:
            self.trust_scores[donor_id] = max(0.0, self.trust_scores.get(donor_id, 0.5) - 0.02)
        if recipient_action == 'cooperate':
            self.trust_scores[recipient_id] = min(1.0, self.trust_scores.get(recipient_id, 0.5) + 0.015)
        else:
            self.trust_scores[recipient_id] = max(0.0, self.trust_scores.get(recipient_id, 0.5) - 0.02)

    def _update_emotional_memory(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_id not in self.emotional_memory:
            self.emotional_memory[donor_id] = 0.0
        if recipient_id not in self.emotional_memory:
            self.emotional_memory[recipient_id] = 0.0

        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.emotional_memory[donor_id] = min(1.0, self.emotional_memory[donor_id] + 0.1)
            self.emotional_memory[recipient_id] = min(1.0, self.emotional_memory[recipient_id] + 0.1)
        elif donor_action == 'defect' and recipient_action == 'defect':
            self.emotional_memory[donor_id] = max(-1.0, self.emotional_memory[donor_id] - 0.1)
            self.emotional_memory[recipient_id] = max(-1.0, self.emotional_memory[recipient_id] - 0.1)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            self.emotional_memory[donor_id] = max(-1.0, self.emotional_memory[donor_id] - 0.05)
            self.emotional_memory[recipient_id] = min(1.0, self.emotional_memory[recipient_id] + 0.05)
        elif donor_action == 'defect' and recipient_action == 'cooperate':
            self.emotional_memory[donor_id] = min(1.0, self.emotional_memory[donor_id] + 0.05)
            self.emotional_memory[recipient_id] = max(-1.0, self.emotional_memory[recipient_id] - 0.05)

    def _update_reputation_confidence(self, agent_id: int, action: str) -> None:
        current_rep = self.reputation_scores.get(agent_id, 0.5)
        confidence = self.reputation_confidence.get(agent_id, 0.5)
        if (action == 'cooperate' and current_rep > 0.5) or (action == 'defect' and current_rep < 0.5):
            new_conf = confidence + 0.05
        else:
            new_conf = confidence - 0.05

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.interaction_stats = {}
        self.self_actions = []
        self.base_coop_prob = 0.7
        self.recent_outcomes = []
        self.observed_count = 0
        self.reputation_scores = {}
        self.forgiveness = {}
        self.trust_decay = {}
        self.betrayal_count = {}
        self.betrayal_streak = {}
        self.mutual_coop_count = {}
        self.third_party_records = {}
        self.opponent_recent_coop = {}
        self.opponent_action_history = {}
        self.opponent_conditional = {}
        self.recent_coop_rate = {}
        self.total_observed_actions = {}
        self.observed_coop_count = {}
        self.punishment_count = {}
        self.third_party_betrayal_count = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        stats = self.interaction_stats.get(opponent_id, {})
        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        opp_defect_when_coop = 0
        if (cc + cd) > 0:
            opp_defect_when_coop = cd / (cc + cd)

        rep_score = self.reputation_scores.get(opponent_id, 0)
        rep_factor = max(-0.5, min(0.5, rep_score / 20.0))

        forgive = self.forgiveness.get(opponent_id, 0)
        forgive_factor = max(0, min(0.3, forgive * 0.05))

        decay = self.trust_decay.get(opponent_id, 0)
        decay_factor = max(-0.4, min(0.0, -decay * 0.02))

        betrayals = self.betrayal_count.get(opponent_id, 0)
        betrayal_factor = max(-0.3, min(0.0, -betrayals * 0.05))

        streak = self.betrayal_streak.get(opponent_id, 0)
        streak_factor = max(-0.4, min(0.0, -streak * 0.1))

        mutual = self.mutual_coop_count.get(opponent_id, 0)
        mutual_factor = min(0.3, mutual * 0.02)

        recent_coop = self.opponent_recent_coop.get(opponent_id, [])
        recent_avg = sum(recent_coop) / len(recent_coop) if recent_coop else 0.5
        recent_factor = (recent_avg - 0.5) * 0.2

        history = self.opponent_action_history.get(opponent_id, [])
        pattern_factor = 0.0
        if len(history) >= 3:
            coop_after_my_coop = 0
            coop_after_my_coop_total = 0
            for i in range(len(history)-1):
                if history[i][0] == 'cooperate':
                    coop_after_my_coop_total += 1
                    if history[i+1][1] == 'cooperate':
                        coop_after_my_coop += 1
            if coop_after_my_coop_total > 0:
                ratio = coop_after_my_coop / coop_after_my_coop_total
                pattern_factor = (ratio - 0.5) * 0.15

        recent_rate = self.recent_coop_rate.get(opponent_id, 0.5)
        recent_rate_factor = (recent_rate - 0.5) * 0.1

        observed_total = self.total_observed_actions.get(opponent_id, 0)
        observed_coop = self.observed_coop_count.get(opponent_id, 0)
        observed_freq = observed_coop / observed_total if observed_total > 0 else 0.5
        observed_freq_factor = (observed_freq - 0.5) * 0.15

        # New: punish agents that defect against others (third-party punishment)
        punish_count = self.punishment_count.get(opponent_id, 0)
        punish_factor = max(-0.25, min(0.0, -punish_count * 0.08))

        # New: additional punishment for repeated third-party betrayals
        third_party_betrayals = self.third_party_betrayal_count.get(opponent_id, 0)
        third_party_betrayal_factor = max(-0.2, min(0.0, -third_party_betrayals * 0.06))

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor
        prob += recent_factor
        prob += pattern_factor
        prob += recent_rate_factor
        prob += observed_freq_factor
        prob += punish_factor
        prob += third_party_betrayal_factor
        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

