        third_party_actions = self.third_party_action_counts.get(opponent_id, [])
        if len(third_party_actions) >= 2:
            changes = sum(1 for i in range(1, len(third_party_actions)) if third_party_actions[i] != third_party_actions[i-1])
            vol = changes / (len(third_party_actions) - 1)
            prob -= vol * 0.15

        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

