            if history[i][0] == 'cooperate' and history[i+1][0] == 'defect':
                my_defect_after_coop += 1
            if history[i][0] == 'cooperate':
                my_defect_after_coop_total += 1
        if my_defect_after_coop_total > 0:
            my_defect_ratio = my_defect_after_coop / my_defect_after_coop_total
            my_defect_penalty = (my_defect_ratio - 0.5) * 0.1
        else:
            my_defect_penalty = 0.0

        donor_rate = self.donor_coop_rate.get(opponent_id, 0.5)
        recipient_rate = self.recipient_coop_rate.get(opponent_id, 0.5)
        role_factor = (donor_rate - 0.5) * 0.1 + (recipient_rate - 0.5) * 0.1

        # New: Reciprocity factor - reward opponents who cooperate after I cooperate
        recip_opps = self.reciprocity_opportunities.get(opponent_id, 0)
        recip_coops = self.reciprocity.get(opponent_id, 0)
        recip_ratio = recip_coops / recip_opps if recip_opps > 0 else 0.5
        reciprocity_factor = (recip_ratio - 0.5) * 0.2

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor
        prob += recent_factor
        prob += pattern_factor
        prob += recent_rate_factor
        prob += observed_freq_factor
        prob += punish_factor
        prob += third_party_betrayal_factor
        prob += coop_streak_factor
        prob -= my_defect_penalty
        prob += role_factor
        prob += reciprocity_factor
        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

