        if recent_total > 0:
            recent_def_rate = recent_def / recent_total
            prob -= recent_def_rate * 0.2

        my_coop = self.my_coop_with_opponent.get(opponent_id, 0)
        prob += min(0.2, my_coop * 0.01)

        opp_def_after_coop = self.opponent_defect_after_my_coop.get(opponent_id, 0)
        opp_coop_after_coop = self.opponent_coop_after_my_coop.get(opponent_id, 0)
        total_after_coop = opp_def_after_coop + opp_coop_after_coop
        if total_after_coop > 0:
            cond_def_rate = opp_def_after_coop / total_after_coop
            prob -= cond_def_rate * 0.4

        opp_def_after_defect = self.opponent_response_after_my_defect.get(opponent_id, {}).get('defect', 0)
        opp_coop_after_defect = self.opponent_response_after_my_defect.get(opponent_id, {}).get('cooperate', 0)
        total_after_defect = opp_def_after_defect + opp_coop_after_defect
        if total_after_defect > 0:
            cond_def_rate_after_defect = opp_def_after_defect / total_after_defect
            prob -= cond_def_rate_after_defect * 0.2

        if total_after_defect > 0:
            coop_after_defect_rate = opp_coop_after_defect / total_after_defect
            prob += coop_after_defect_rate * 0.1

        my_coop_streak = self.coop_streak.get(opponent_id, 0)
        my_defect_streak = self.defect_streak.get(opponent_id, 0)
        if my_defect_streak > 0:
            prob -= min(0.3, my_defect_streak * 0.05)
        if my_coop_streak > 0:
            prob += min(0.2, my_coop_streak * 0.03)

