        if third_party_total > 0:
            third_party_coop_rate = third_party_coop / third_party_total
            prob += (third_party_coop_rate - 0.5) * 0.15

        # New: if we cooperated last time with this opponent, be slightly more cooperative
        last_coop = self.last_cooperation_with.get(opponent_id, False)
        if last_coop:
            prob += 0.05

        prob = max(0.05, min(0.95, prob))

