        role_factor = (donor_rate - 0.5) * 0.1 + (recipient_rate - 0.5) * 0.1

        # New: Reciprocity factor - if opponent tends to reciprocate my cooperation, cooperate more
        recip = self.reciprocity.get(opponent_id, 0.5)
        recip_factor = (recip - 0.5) * 0.2

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
