        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        self.reputation_scores[donor_id] = self.reputation_scores.get(donor_id, 0) + (1 if donor_action == 'cooperate' else -1)
        self.reputation_scores[recipient_id] = self.reputation_scores.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else -1)

