import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.interaction_stats = {}
        self.self_actions = []
        self.base_coop_prob = 0.7
        self.recent_outcomes = []
        self.observed_count = 0
        self.opp_response_after_my_coop = {}
        self.opp_response_after_my_defect = {}
        self.trust_scores = {}
        self.reputation_scores = {}
        self.punishment_scores = {}
        self.forgiveness_scores = {}
        self.recent_opponent_actions = {}
        self.reciprocity_index = 0.5
        self.emotional_memory = {}
        self.reputation_confidence = {}
        self.defect_penalty = {}
        self.coop_bonus = {}
        self.third_party_observations = {}
        self.third_party_defect_count = {}
        self.third_party_coop_count = {}
        self.last_opponent_id = None
        self.last_my_action = None
        self.last_opponent_action = None
        self.aggression_factor = 0.0

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        trust = self.trust_scores.get(opponent_id, 0.5)
        reputation = self.reputation_scores.get(opponent_id, 0.5)
        punishment = self.punishment_scores.get(opponent_id, 0.0)
        forgiveness = self.forgiveness_scores.get(opponent_id, 0.5)

        recent_actions = self.recent_opponent_actions.get(opponent_id, [])
        if len(recent_actions) >= 3:
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.reciprocity_index = coop_count / len(recent_actions)
        else:
            self.reciprocity_index = 0.5

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.3
        prob += (trust - 0.5) * 0.2
        prob += (reputation - 0.5) * 0.1
        prob -= punishment * 0.3
        prob += (forgiveness - 0.5) * 0.15
        prob += (self.reciprocity_index - 0.5) * 0.25

        defect_pen = self.defect_penalty.get(opponent_id, 0.0)
        coop_bonus = self.coop_bonus.get(opponent_id, 0.0)
        prob -= defect_pen * 0.2
        prob += coop_bonus * 0.2

        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob += (coop_rate_after - 0.5) * 0.4

        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.2

        third_party = self.third_party_observations.get(opponent_id, 0.0)
        prob += third_party * 0.15

        third_party_defects = self.third_party_defect_count.get(opponent_id, 0)
        if third_party_defects > 2:
            prob -= min(0.3, third_party_defects * 0.02)

        third_party_coops = self.third_party_coop_count.get(opponent_id, 0)
        third_party_total = third_party_coops + third_party_defects
        if third_party_total > 2:
            third_party_coop_rate = third_party_coops / third_party_total
            prob += (third_party_coop_rate - 0.5) * 0.2

        if total >= 5:
            prob += (opp_coop_rate - 0.5) * 0.1

        if len(self.recent_outcomes) >= 5:
            avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_payoff > 2.8:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.02)
            elif avg_payoff < 2.2:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.02)

        emotional = self.emotional_memory.get(opponent_id, 0.0)
        prob += emotional * 0.1

        confidence = self.reputation_confidence.get(opponent_id, 0.5)
        prob += (confidence - 0.5) * 0.1

        if self.last_opponent_id == opponent_id and self.last_my_action == 'cooperate' and self.last_opponent_action == 'cooperate':
            prob += 0.15

        # Mutation: dynamic aggression factor based on recent interactions
        if opponent_id in self.interaction_stats:
            stats = self.interaction_stats[opponent_id]
            total_interactions = sum(stats.values())
            if total_interactions > 0:
                coop_coop = stats.get('CC', 0)
                coop_defect = stats.get('CD', 0)
                defect_coop = stats.get('DC', 0)
                defect_defect = stats.get('DD', 0)
                if total_interactions >= 5:
                    betrayal_rate = (coop_defect + defect_defect) / total_interactions
                    target_aggression = max(0.0, min(0.3, (betrayal_rate - 0.3) * 0.5))
                    self.aggression_factor = 0.8 * self.aggression_factor + 0.2 * target_aggression
                else:
                    self.aggression_factor *= 0.95
                prob -= self.aggression_factor

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

        self._update_trust(donor_id, donor_action)
        self._update_trust(recipient_id, recipient_action)
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        self._update_punishment_and_forgiveness(donor_id, donor_action, recipient_id, recipient_action)

        if donor_id != self.agent_id and recipient_id != self.agent_id:
            self._update_third_party_trust(donor_id, donor_action, recipient_id, recipient_action)
            self._update_third_party_patterns(donor_id, donor_action, recipient_id, recipient_action)
            if donor_action == 'defect':
                self.third_party_defect_count[donor_id] = self.third_party_defect_count.get(donor_id, 0) + 1
            else:
                self.third_party_coop_count[donor_id] = self.third_party_coop_count.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.third_party_defect_count[recipient_id] = self.third_party_defect_count.get(recipient_id, 0) + 1
            else:
                self.third_party_coop_count[recipient_id] = self.third_party_coop_count.get(recipient_id, 0) + 1

