                self.recent_opponent_actions[opponent_id] = []
            self.recent_opponent_actions[opponent_id].append(opp_action)
            if len(self.recent_opponent_actions[opponent_id]) > 10:
                self.recent_opponent_actions[opponent_id].pop(0)

            if my_action == 'cooperate':
                if opponent_id not in self.opp_response_after_my_coop:
                    self.opp_response_after_my_coop[opponent_id] = [0, 0]
                if opp_action == 'cooperate':
                    self.opp_response_after_my_coop[opponent_id][0] += 1
                else:
                    self.opp_response_after_my_coop[opponent_id][1] += 1
            else:
                if opponent_id not in self.opp_response_after_my_defect:
