        observed_freq_factor = (observed_freq - 0.5) * 0.15

        punish_count = self.punishment_count.get(opponent_id, 0)
        punish_factor = max(-0.25, min(0.0, -punish_count * 0.08))

        third_party_betrayals = self.third_party_betrayal_count.get(opponent_id, 0)
        third_party_betrayal_factor = max(-0.2, min(0.0, -third_party_betrayals * 0.06))

        coop_streak = self.coop_streak.get(opponent_id, 0)
        coop_streak_factor = min(0.2, coop_streak * 0.03)

        my_defect_after_coop = 0
        my_defect_after_coop_total = 0
        for i in range(len(history)-1):
