        altruism = self.opponent_altruism.get(opponent_id, 0.5)
        altruism_factor = (altruism - 0.5) * 0.2

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor
        prob += recent_factor
        prob += pattern_factor
        prob += recent_rate_factor
        prob += observed_freq_factor
        prob += punish_factor
        prob += third_party_betrayal_factor
        prob += coop_streak_factor
        prob -= my_defect_penalty
        prob -= opp_defect_penalty
        prob += altruism_factor
        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
