import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.interaction_stats = {}
        self.self_actions = []
        self.base_coop_prob = 0.7
        self.recent_outcomes = []
        self.observed_count = 0
        self.reputation_scores = {}
        self.forgiveness = {}
        self.trust_decay = {}
        self.betrayal_count = {}
        self.betrayal_streak = {}
        self.mutual_coop_count = {}
        self.third_party_records = {}
        self.opponent_coop_probs = {}
        self.opponent_volatility = {}
        self.opponent_consistency = {}
        self.last_opponent_action = {}
        self.opponent_recent_actions = {}
        self.reciprocation_count = {}
        self.reciprocation_opportunities = {}
        self.opponent_recent_defections = {}
        self.my_coop_with_opponent = {}
        self.opponent_response_stats = {}
        self.trust_by_action = {}
        self.recent_defection_streaks = {}
        # New: track long-term cooperation history for each opponent
        self.long_term_coop_history = {}
        # New: track opponent's cooperation after my defection
        self.opponent_coop_after_my_defect = {}
        self.opponent_defect_after_my_defect = {}
        # New: track opponent's cooperation after they defect (forgiveness)
        self.opponent_coop_after_their_defect = {}
        self.opponent_defect_after_their_defect = {}
        # New: track third-party observations for indirect reciprocity
        self.third_party_coop_counts = {}
        self.third_party_defect_counts = {}
        self.third_party_observation_count = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        stats = self.interaction_stats.get(opponent_id, {})
        cc = stats.get('CC', 0)
        cd = stats.get('CD', 0)
        dc = stats.get('DC', 0)
        dd = stats.get('DD', 0)
        hist_total = cc + cd + dc + dd
        opp_defect_when_coop = 0
        if (cc + cd) > 0:
            opp_defect_when_coop = cd / (cc + cd)

        rep_score = self.reputation_scores.get(opponent_id, 0)
        rep_factor = max(-0.5, min(0.5, rep_score / 20.0))

        forgive = self.forgiveness.get(opponent_id, 0)
        forgive_factor = max(0, min(0.3, forgive * 0.05))

        decay = self.trust_decay.get(opponent_id, 0)
        decay_factor = max(-0.4, min(0.0, -decay * 0.02))

        betrayals = self.betrayal_count.get(opponent_id, 0)
        betrayal_factor = max(-0.3, min(0.0, -betrayals * 0.05))

        streak = self.betrayal_streak.get(opponent_id, 0)
        streak_factor = max(-0.4, min(0.0, -streak * 0.1))

        mutual = self.mutual_coop_count.get(opponent_id, 0)
        mutual_factor = min(0.3, mutual * 0.02)

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor

        opp_prob = self.opponent_coop_probs.get(opponent_id, 0.5)
        prob += (opp_prob - 0.5) * 0.3

        volatility = self.opponent_volatility.get(opponent_id, 0.0)
        prob -= volatility * 0.2
        prob += (1.0 - volatility) * 0.05

        consistency = self.opponent_consistency.get(opponent_id, 0.5)
        if opp_coop_rate > 0.5:
            prob += (consistency - 0.5) * 0.2
        else:
            prob -= (consistency - 0.5) * 0.2

        recip_opp = self.reciprocation_opportunities.get(opponent_id, 0)
        recip_count = self.reciprocation_count.get(opponent_id, 0)
        recip_rate = recip_count / recip_opp if recip_opp > 0 else 0.5
        prob += (recip_rate - 0.5) * 0.3

        recent = self.opponent_recent_actions.get(opponent_id, [])
        if recent:
            last_action = recent[-1]
            if last_action == 'cooperate':
                prob += 0.1
            else:
                prob -= 0.1

        recent_def = self.opponent_recent_defections.get(opponent_id, 0)
        recent_total = len(recent)
        if recent_total > 0:
            recent_def_rate = recent_def / recent_total
            prob -= recent_def_rate * 0.2

        my_coop = self.my_coop_with_opponent.get(opponent_id, 0)
        prob += min(0.2, my_coop * 0.01)

        resp_stats = self.opponent_response_stats.get(opponent_id, {})
        coop_after_coop = resp_stats.get('coop_after_coop', 0)
        coop_after_coop_total = resp_stats.get('coop_after_coop_total', 0)
        if coop_after_coop_total > 0:
            coop_after_coop_rate = coop_after_coop / coop_after_coop_total
            prob += (coop_after_coop_rate - 0.5) * 0.3

        trust_key = (self.last_opponent_action.get(opponent_id), 'cooperate')
        trust_val = self.trust_by_action.get((opponent_id, trust_key), 0.5)
        prob += (trust_val - 0.5) * 0.2

        streak_len = self.recent_defection_streaks.get(opponent_id, 0)
        if streak_len > 0:
            prob -= streak_len * 0.15

        # New: incorporate long-term cooperation history
        long_term = self.long_term_coop_history.get(opponent_id, 0)
        if long_term > 0:
            long_term_rate = long_term / (long_term + self.defect_counts.get(opponent_id, 0) + 1)
            prob += (long_term_rate - 0.5) * 0.2

        # New: if opponent cooperates after my defection, increase trust
        my_defect_total = self.opponent_defect_after_my_defect.get(opponent_id, 0) + self.opponent_coop_after_my_defect.get(opponent_id, 0)
        if my_defect_total > 0:
            coop_after_defect_rate = self.opponent_coop_after_my_defect.get(opponent_id, 0) / my_defect_total
            prob += (coop_after_defect_rate - 0.5) * 0.4

        # New: if opponent cooperates after their own defection (forgiveness factor)
        their_defect_total = self.opponent_defect_after_their_defect.get(opponent_id, 0) + self.opponent_coop_after_their_defect.get(opponent_id, 0)
        if their_defect_total > 0:
            coop_after_their_defect_rate = self.opponent_coop_after_their_defect.get(opponent_id, 0) / their_defect_total
            prob += (coop_after_their_defect_rate - 0.5) * 0.2

        # New: incorporate third-party observation of opponent's behavior
        third_party_coop = self.third_party_coop_counts.get(opponent_id, 0)
        third_party_def = self.third_party_defect_counts.get(opponent_id, 0)
        third_party_total = third_party_coop + third_party_def
        if third_party_total > 0:
            third_party_coop_rate = third_party_coop / third_party_total
            prob += (third_party_coop_rate - 0.5) * 0.3

        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

