        my_defect_after_coop_total = 0
        for i in range(len(history)-1):
            if history[i][0] == 'cooperate' and history[i+1][0] == 'defect':
                my_defect_after_coop += 1
            if history[i][0] == 'cooperate':
                my_defect_after_coop_total += 1
        if my_defect_after_coop_total > 0:
            my_defect_ratio = my_defect_after_coop / my_defect_after_coop_total
            my_defect_penalty = (my_defect_ratio - 0.5) * 0.1
