        # New factors: prosociality and reciprocity
        prosocial = self.prosociality.get(opponent_id, 0.5)
        prosocial_factor = (prosocial - 0.5) * 0.15

        reciprocity = self.reciprocity.get(opponent_id, 0.5)
        reciprocity_factor = (reciprocity - 0.5) * 0.15

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.6
        prob -= opp_defect_when_coop * 0.8
        prob += rep_factor
        prob += forgive_factor
        prob += decay_factor
        prob += betrayal_factor
        prob += streak_factor
        prob += mutual_factor
        prob += recent_factor
        prob += pattern_factor
        prob += recent_rate_factor
        prob += observed_freq_factor
        prob += punish_factor
        prob += third_party_betrayal_factor
        prob += coop_streak_factor
        prob -= my_defect_penalty
        prob -= opp_defect_penalty
        prob += altruism_factor
        prob += prosocial_factor
        prob += reciprocity_factor
        prob = max(0.05, min(0.95, prob))

        return random.random() < prob

