        if recipient_action == 'cooperate':
            self.total_coop_global[recipient_id] = self.total_coop_global.get(recipient_id, 0) + 1
        else:
            self.total_defect_global[recipient_id] = self.total_defect_global.get(recipient_id, 0) + 1

        self._update_trust(donor_id, donor_action)
        self._update_trust(recipient_id, recipient_action)
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

