        self._update_defect_penalty(recipient_id, recipient_action)
        self._update_coop_bonus(donor_id, donor_action)
        self._update_coop_bonus(recipient_id, recipient_action)

        # New: track reputation changes over time
        for agent in [donor_id, recipient_id]:
            if agent in self.past_reputation:
                self.opponent_rep_change[agent] = self.reputation_scores.get(agent, 0.5) - self.past_reputation[agent]
            self.past_reputation[agent] = self.reputation_scores.get(agent, 0.5)

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                opponent_id = recipient_id
                my_action = donor_action
                opp_action = recipient_action
            else:
                opponent_id = donor_id
                my_action = recipient_action
                opp_action = donor_action
            key = my_action[0].upper() + opp_action[0].upper()
