        count = self.interaction_count.get(opponent_id, 0)
        if count >= 5:
            # If high variance and low cooperation, be more cautious
            if variance > 0.2 and lt_rate < 0.3:
                prob -= 0.15
            # If stable cooperation, reward reliability
            if variance < 0.05 and lt_rate > 0.7:
                prob += 0.1

