        self.reputation_scores[agent_id] = max(0.0, min(1.0, new))

    def _update_punishment_and_forgiveness(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'defect' and recipient_action == 'cooperate':
