        if streak_len > 0:
            prob -= streak_len * 0.15

        long_term = self.long_term_coop_history.get(opponent_id, 0)
        if long_term > 0:
            long_term_rate = long_term / (long_term + self.defect_counts.get(opponent_id, 0) + 1)
            prob += (long_term_rate - 0.5) * 0.2

