        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.2

        # New logic: Use detailed response after my defection
        # If opponent usually cooperates after my defection, we might still defect
        # If opponent usually defects after my defection, we should avoid defecting
        if opponent_id in self.opp_coop_after_my_defect:
            coop_after = self.opp_coop_after_my_defect[opponent_id]
            defect_after = self.opp_defect_after_my_defect[opponent_id]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                # If opponent is forgiving (cooperates after my defect), we can defect more
                prob += (coop_rate_after - 0.5) * 0.25
                # If opponent retaliates (defects after my defect), we should defect less
                prob -= (defect_after / total_after) * 0.15

        third_party = self.third_party_observations.get(opponent_id, 0.0)
        prob += third_party * 0.15

        third_party_defects = self.third_party_defect_count.get(opponent_id, 0)
        if third_party_defects > 2:
            prob -= min(0.3, third_party_defects * 0.02)

