            mirror_rate = mirror_count / 4
            prob += (mirror_rate - 0.5) * 0.3

        venge = self.vengefulness.get(opponent_id, 0.0)
        prob -= venge * 0.15

        # New: Use recent cooperation ratio to adjust probability
        recent_ratio = self.recent_coop_ratio.get(opponent_id, 0.5)
