        decay = self.trust_decay.get(opponent_id, 0.0)
        prob -= decay * 0.1

        # New: adaptation factor - amplify cooperation when trust is high
        prob += (trust - 0.5) * (self.adaptation_factor - 1.0) * 0.2

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

