            prob += (global_coop_rate - 0.5) * 0.2

        personal = self.personal_interactions.get(opponent_id, [])
        if len(personal) >= 4:
            mirror_count = 0
            for my, opp in personal[-4:]:
                if (my == 'cooperate' and opp == 'cooperate') or (my == 'defect' and opp == 'defect'):
                    mirror_count += 1
            mirror_rate = mirror_count / 4
            prob += (mirror_rate - 0.5) * 0.3

        venge = self.vengefulness.get(opponent_id, 0.0)
        prob -= venge * 0.15

        third_party_trust = self.third_party_trust.get(opponent_id, 0.0)
        prob += third_party_trust * 0.2

        consistency = self.coop_pattern_consistency.get(opponent_id, 0.0)
