    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        trust = self.trust_scores.get(opponent_id, 0.5)
        reputation = self.reputation_scores.get(opponent_id, 0.5)
        punishment = self.punishment_scores.get(opponent_id, 0.0)
        forgiveness = self.forgiveness_scores.get(opponent_id, 0.5)

        recent_actions = self.recent_opponent_actions.get(opponent_id, [])
        if len(recent_actions) >= 3:
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.reciprocity_index = coop_count / len(recent_actions)
        else:
            self.reciprocity_index = 0.5

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.3
        prob += (trust - 0.5) * 0.2
        prob += (reputation - 0.5) * 0.1
        prob -= punishment * 0.3
        prob += (forgiveness - 0.5) * 0.15
        prob += (self.reciprocity_index - 0.5) * 0.25

        defect_pen = self.defect_penalty.get(opponent_id, 0.0)
        coop_bonus = self.coop_bonus.get(opponent_id, 0.0)
