    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.coop_counts = {}
        self.defect_counts = {}
        self.interaction_stats = {}
        self.self_actions = []
        self.base_coop_prob = 0.7
        self.recent_outcomes = []
        self.observed_count = 0
        self.opp_response_after_my_coop = {}
        self.opp_response_after_my_defect = {}
        self.trust_scores = {}
        self.reputation_scores = {}
        self.punishment_scores = {}
        self.forgiveness_scores = {}
        self.recent_opponent_actions = {}
        self.reciprocity_index = 0.5
        self.emotional_memory = {}
        self.reputation_confidence = {}
        self.defect_penalty = {}
        self.coop_bonus = {}
        self.third_party_observations = {}
        self.third_party_defect_count = {}
        self.third_party_coop_count = {}
        self.last_opponent_id = None
        self.last_my_action = None
        self.last_opponent_action = None
        # New: track cooperation streak with each opponent for adaptive reciprocity
        self.coop_streak = {}
        self.defect_streak = {}
        # New: track long-term cooperation rate and variance for risk assessment
        self.long_term_coop_rate = {}
        self.coop_variance = {}
        self.interaction_count = {}
        # New: track mutual cooperation history for trust reinforcement
        self.mutual_coop_count = {}
        self.mutual_defect_count = {}
        # New: track recent defection rate to detect exploitative behavior
        self.recent_defect_rate = {}
        self.recent_interaction_count = {}
        # New: track opponent's action after my defection for forgiveness learning
        self.forgiveness_learning = {}
        # New: track third-party observation consistency
        self.third_party_consistency = {}
        # New: track opponent's volatility (action changes)
        self.opponent_volatility = {}
        self.opponent_prev_action = {}
        # New: track opponent's cooperation patterns in rounds, for time-based adjustments
        self.round_cooperation = {}
        self.round_defection = {}
        # New: track the last action each opponent took when we interacted, for adaptive trust
        self.last_action_against = {}
        # New: track the number of times we have interacted with each opponent
        self.total_interactions = {}
        # New: track the number of times the opponent has defected in a row
        self.opp_defect_streak = {}
        # New: track opponent's generosity (cooperation when they are donor)
        self.opponent_generosity = {}
        # New: track opponent's reciprocity (cooperation when they are recipient)
        self.opponent_reciprocity = {}
        # New: track opponent's consistency in third-party observations
        self.third_party_trust = {}
        # New: track recent cooperation rate for each opponent
        self.recent_coop_rate = {}
        self.recent_action_count = {}

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        trust = self.trust_scores.get(opponent_id, 0.5)
        reputation = self.reputation_scores.get(opponent_id, 0.5)
        punishment = self.punishment_scores.get(opponent_id, 0.0)
        forgiveness = self.forgiveness_scores.get(opponent_id, 0.5)

        recent_actions = self.recent_opponent_actions.get(opponent_id, [])
        if len(recent_actions) >= 3:
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.reciprocity_index = coop_count / len(recent_actions)
        else:
            self.reciprocity_index = 0.5

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.3
        prob += (trust - 0.5) * 0.2
        prob += (reputation - 0.5) * 0.1
        prob -= punishment * 0.3
        prob += (forgiveness - 0.5) * 0.15
        prob += (self.reciprocity_index - 0.5) * 0.25

        defect_pen = self.defect_penalty.get(opponent_id, 0.0)
        coop_bonus = self.coop_bonus.get(opponent_id, 0.0)
        prob -= defect_pen * 0.2
        prob += coop_bonus * 0.2

        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob += (coop_rate_after - 0.5) * 0.4

        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.2

        third_party = self.third_party_observations.get(opponent_id, 0.0)
        prob += third_party * 0.15

        third_party_defects = self.third_party_defect_count.get(opponent_id, 0)
        if third_party_defects > 2:
            prob -= min(0.3, third_party_defects * 0.02)

        third_party_coops = self.third_party_coop_count.get(opponent_id, 0)
        third_party_total = third_party_coops + third_party_defects
        if third_party_total > 2:
            third_party_coop_rate = third_party_coops / third_party_total
            prob += (third_party_coop_rate - 0.5) * 0.2

        if total >= 5:
            prob += (opp_coop_rate - 0.5) * 0.1

        if len(self.recent_outcomes) >= 5:
            avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_payoff > 2.8:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.02)
            elif avg_payoff < 2.2:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.02)

        emotional = self.emotional_memory.get(opponent_id, 0.0)
        prob += emotional * 0.1

        confidence = self.reputation_confidence.get(opponent_id, 0.5)
        prob += (confidence - 0.5) * 0.1

        # New: adaptive streak-based adjustment
        my_streak = self.coop_streak.get(opponent_id, 0)
        opp_streak = self.defect_streak.get(opponent_id, 0)
        if my_streak >= 3 and opp_streak == 0:
            prob += 0.1  # Reward sustained cooperation
        if opp_streak >= 3:
            prob -= 0.2  # Punish opponent's defect streak

        # New: if the opponent cooperated last time we interacted and we cooperated, increase cooperation prob
        if self.last_opponent_id == opponent_id and self.last_my_action == 'cooperate' and self.last_opponent_action == 'cooperate':
            prob += 0.15

        # New: risk assessment based on variance and long-term cooperation
        lt_rate = self.long_term_coop_rate.get(opponent_id, 0.5)
        variance = self.coop_variance.get(opponent_id, 0.1)
        count = self.interaction_count.get(opponent_id, 0)
        if count >= 5:
            # If high variance and low cooperation, be more cautious
            if variance > 0.2 and lt_rate < 0.3:
                prob -= 0.15
            # If stable cooperation, reward reliability
            if variance < 0.05 and lt_rate > 0.7:
                prob += 0.1

        # New: mutual cooperation history reinforcement
        mc = self.mutual_coop_count.get(opponent_id, 0)
        md = self.mutual_defect_count.get(opponent_id, 0)
        mutual_total = mc + md
        if mutual_total > 0:
            mutual_coop_rate = mc / mutual_total
            prob += (mutual_coop_rate - 0.5) * 0.3

        # New: detect exploitative patterns - if opponent defects often after we cooperate
        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after >= 3:
                exploit_rate = defect_after / total_after
                if exploit_rate > 0.7:
                    prob -= 0.25
                elif exploit_rate > 0.5:
                    prob -= 0.1

        # New: recent defection rate adjustment
        recent_def_rate = self.recent_defect_rate.get(opponent_id, 0.0)
        if recent_def_rate > 0.5:
            prob -= min(0.2, recent_def_rate * 0.2)

        # New: forgiveness learning - if opponent cooperated after my defection, increase forgiveness
        forgiveness_learn = self.forgiveness_learning.get(opponent_id, 0.0)
        prob += forgiveness_learn * 0.1

        # New: third-party consistency adjustment
        consistency = self.third_party_consistency.get(opponent_id, 0.0)
        prob += (consistency - 0.5) * 0.1

        # New: opponent volatility adjustment - if opponent is erratic, be more cautious
        volatility = self.opponent_volatility.get(opponent_id, 0.0)
        prob -= volatility * 0.15

        # New: time-based adjustment - if opponent has been cooperative in recent rounds, reward
        round_coop = self.round_cooperation.get(opponent_id, 0)
        round_def = self.round_defection.get(opponent_id, 0)
        round_total = round_coop + round_def
        if round_total >= 3:
            round_coop_rate = round_coop / round_total
            prob += (round_coop_rate - 0.5) * 0.2

        # New: adaptive trust based on last action against this opponent
        last_action = self.last_action_against.get(opponent_id, None)
        if last_action is not None:
            if last_action == 'cooperate':
                prob += 0.1  # Reward opponent's last cooperation
            else:
                prob -= 0.1  # Penalize opponent's last defection

        # New: opponent defect streak - more severe penalty for longer streaks
        opp_def_streak = self.opp_defect_streak.get(opponent_id, 0)
        if opp_def_streak >= 2:
            prob -= min(0.3, opp_def_streak * 0.1)

        # New: opponent generosity and reciprocity adjustments
        generosity = self.opponent_generosity.get(opponent_id, 0.5)
        reciprocity = self.opponent_reciprocity.get(opponent_id, 0.5)
        prob += (generosity - 0.5) * 0.1
        prob += (reciprocity - 0.5) * 0.1

        # New: recent cooperation rate adjustment
        recent_rate = self.recent_coop_rate.get(opponent_id, 0.5)
        prob += (recent_rate - 0.5) * 0.15

        # New: third-party trust adjustment
        third_party_trust = self.third_party_trust.get(opponent_id, 0.5)
        prob += (third_party_trust - 0.5) * 0.1

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)
        self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
        self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + (1 if recipient_action == 'defect' else 0)

