        if my_streak >= 3 and opp_streak == 0:
            prob += 0.1
        if opp_streak >= 3:
            prob -= 0.2

        if self.last_opponent_id == opponent_id and self.last_my_action == 'cooperate' and self.last_opponent_action == 'cooperate':
            prob += 0.15

        global_coop = self.total_coop_global.get(opponent_id, 0)
        global_defect = self.total_defect_global.get(opponent_id, 0)
        global_total = global_coop + global_defect
        if global_total > 0:
            global_coop_rate = global_coop / global_total
            prob += (global_coop_rate - 0.5) * 0.2

        personal = self.personal_interactions.get(opponent_id, [])
        if len(personal) >= 4:
            mirror_count = 0
            for my, opp in personal[-4:]:
                if (my == 'cooperate' and opp == 'cooperate') or (my == 'defect' and opp == 'defect'):
                    mirror_count += 1
            mirror_rate = mirror_count / 4
            prob += (mirror_rate - 0.5) * 0.3

        venge = self.vengefulness.get(opponent_id, 0.0)
        prob -= venge * 0.15

        decay = self.trust_decay.get(opponent_id, 0.0)
        prob -= decay * 0.1

        # New: Incorporate long-term reputation trend
        trend = self.reputation_trend.get(opponent_id, 0.0)
        prob += trend * 0.2

        # New: Use long-term trust as a stabilizing factor
        long_trust = self.long_term_trust.get(opponent_id, 0.5)
        prob += (long_trust - 0.5) * 0.15

        # New: Incorporate opponent consistency to adjust behavior
        consistency = self.opponent_consistency.get(opponent_id, 0.5)
        if consistency > self.adaptive_threshold:
            # If opponent is consistent, rely more on their recent behavior
            prob += (self.reciprocity_index - 0.5) * 0.1
        else:
            # If inconsistent, be more cautious and reduce cooperation probability
            prob -= 0.05

        # New: Add volatility-based randomization to avoid being predictable
        if random.random() < self.volatility:
