            prob += 0.15

        global_coop = self.total_coop_global.get(opponent_id, 0)
        global_defect = self.total_defect_global.get(opponent_id, 0)
        global_total = global_coop + global_defect
        if global_total > 0:
            global_coop_rate = global_coop / global_total
            prob += (global_coop_rate - 0.5) * 0.2

        personal = self.personal_interactions.get(opponent_id, [])
        if len(personal) >= 4:
            mirror_count = 0
            for my, opp in personal[-4:]:
                if (my == 'cooperate' and opp == 'cooperate') or (my == 'defect' and opp == 'defect'):
                    mirror_count += 1
            mirror_rate = mirror_count / 4
            prob += (mirror_rate - 0.5) * 0.3

        venge = self.vengefulness.get(opponent_id, 0.0)
        prob -= venge * 0.15

        # New: trust decay factor - if we haven't interacted recently, reduce trust-based cooperation
        decay = self.trust_decay.get(opponent_id, 0.0)
        prob -= decay * 0.1

        # New: Pattern detection - if opponent tends to cooperate after we defect, be more cooperative with them
        pattern = self.opponent_patterns.get(opponent_id, None)
        if pattern is not None:
            if pattern == 'cooperate_after_my_defect':
                prob += 0.1
            elif pattern == 'defect_after_my_coop':
                prob -= 0.1

        # New: Exploitation awareness - if we've been exploited often, reduce cooperation
        exploitation = self.exploitation_count.get(opponent_id, 0)
        if exploitation > 2:
            prob -= min(0.2, exploitation * 0.02)

