    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return random.random() < self.base_coop_prob

        coop = self.coop_counts.get(opponent_id, 0)
        defect = self.defect_counts.get(opponent_id, 0)
        total = coop + defect
        opp_coop_rate = coop / total if total > 0 else 0.5

        trust = self.trust_scores.get(opponent_id, 0.5)
        reputation = self.reputation_scores.get(opponent_id, 0.5)
        punishment = self.punishment_scores.get(opponent_id, 0.0)
        forgiveness = self.forgiveness_scores.get(opponent_id, 0.5)

        recent_actions = self.recent_opponent_actions.get(opponent_id, [])
        if len(recent_actions) >= 3:
            coop_count = sum(1 for a in recent_actions if a == 'cooperate')
            self.reciprocity_index = coop_count / len(recent_actions)
        else:
            self.reciprocity_index = 0.5

        prob = self.base_coop_prob
        prob += (opp_coop_rate - 0.5) * 0.3
        prob += (trust - 0.5) * 0.2
        prob += (reputation - 0.5) * 0.1
        prob -= punishment * 0.3
        prob += (forgiveness - 0.5) * 0.15
        prob += (self.reciprocity_index - 0.5) * 0.25

        defect_pen = self.defect_penalty.get(opponent_id, 0.0)
        coop_bonus = self.coop_bonus.get(opponent_id, 0.0)
        prob -= defect_pen * 0.2
        prob += coop_bonus * 0.2

        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob += (coop_rate_after - 0.5) * 0.4

        if opponent_id in self.opp_response_after_my_defect:
            coop_after = self.opp_response_after_my_defect[opponent_id][0]
            defect_after = self.opp_response_after_my_defect[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after > 0:
                coop_rate_after = coop_after / total_after
                prob -= (coop_rate_after - 0.5) * 0.2

        third_party = self.third_party_observations.get(opponent_id, 0.0)
        prob += third_party * 0.15

        third_party_defects = self.third_party_defect_count.get(opponent_id, 0)
        if third_party_defects > 2:
            prob -= min(0.3, third_party_defects * 0.02)

        third_party_coops = self.third_party_coop_count.get(opponent_id, 0)
        third_party_total = third_party_coops + third_party_defects
        if third_party_total > 2:
            third_party_coop_rate = third_party_coops / third_party_total
            prob += (third_party_coop_rate - 0.5) * 0.2

        if total >= 5:
            prob += (opp_coop_rate - 0.5) * 0.1

        if len(self.recent_outcomes) >= 5:
            avg_payoff = sum(self.recent_outcomes) / len(self.recent_outcomes)
            if avg_payoff > 2.8:
                self.base_coop_prob = min(0.95, self.base_coop_prob + 0.02)
            elif avg_payoff < 2.2:
                self.base_coop_prob = max(0.05, self.base_coop_prob - 0.02)

        emotional = self.emotional_memory.get(opponent_id, 0.0)
        prob += emotional * 0.1

        confidence = self.reputation_confidence.get(opponent_id, 0.5)
        prob += (confidence - 0.5) * 0.1

        my_streak = self.coop_streak.get(opponent_id, 0)
        opp_streak = self.defect_streak.get(opponent_id, 0)
        if my_streak >= 3 and opp_streak == 0:
            prob += 0.1
        if opp_streak >= 3:
            prob -= 0.2

        if self.last_opponent_id == opponent_id and self.last_my_action == 'cooperate' and self.last_opponent_action == 'cooperate':
            prob += 0.15

        lt_rate = self.long_term_coop_rate.get(opponent_id, 0.5)
        variance = self.coop_variance.get(opponent_id, 0.1)
        count = self.interaction_count.get(opponent_id, 0)
        if count >= 5:
            if variance > 0.2 and lt_rate < 0.3:
                prob -= 0.15
            if variance < 0.05 and lt_rate > 0.7:
                prob += 0.1

        mc = self.mutual_coop_count.get(opponent_id, 0)
        md = self.mutual_defect_count.get(opponent_id, 0)
        mutual_total = mc + md
        if mutual_total > 0:
            mutual_coop_rate = mc / mutual_total
            prob += (mutual_coop_rate - 0.5) * 0.3

        if opponent_id in self.opp_response_after_my_coop:
            coop_after = self.opp_response_after_my_coop[opponent_id][0]
            defect_after = self.opp_response_after_my_coop[opponent_id][1]
            total_after = coop_after + defect_after
            if total_after >= 3:
                exploit_rate = defect_after / total_after
                if exploit_rate > 0.7:
                    prob -= 0.25
                elif exploit_rate > 0.5:
                    prob -= 0.1

        recent_def_rate = self.recent_defect_rate.get(opponent_id, 0.0)
        if recent_def_rate > 0.5:
            prob -= min(0.2, recent_def_rate * 0.2)

        forgiveness_learn = self.forgiveness_learning.get(opponent_id, 0.0)
        prob += forgiveness_learn * 0.1

        consistency = self.third_party_consistency.get(opponent_id, 0.0)
        prob += (consistency - 0.5) * 0.1

        volatility = self.opponent_volatility.get(opponent_id, 0.0)
        prob -= volatility * 0.15

        round_coop = self.round_cooperation.get(opponent_id, 0)
        round_def = self.round_defection.get(opponent_id, 0)
        round_total = round_coop + round_def
        if round_total >= 3:
            round_coop_rate = round_coop / round_total
            prob += (round_coop_rate - 0.5) * 0.2

        last_action = self.last_action_against.get(opponent_id, None)
        if last_action is not None:
            if last_action == 'cooperate':
                prob += 0.1
            else:
                prob -= 0.1

        opp_def_streak = self.opp_defect_streak.get(opponent_id, 0)
        if opp_def_streak >= 2:
            prob -= min(0.3, opp_def_streak * 0.1)

        trust_signal = self.trust_signal_sum.get(opponent_id, 0.0)
        trust_count = self.trust_signal_count.get(opponent_id, 0)
        if trust_count > 0:
            avg_signal = trust_signal / trust_count
            prob += avg_signal * 0.2

        pattern = self.opp_pattern.get(opponent_id, [])
        if len(pattern) >= 4:
            transitions = sum(1 for i in range(1, len(pattern)) if pattern[i] != pattern[i-1])
            if transitions >= len(pattern) - 1:
                prob -= 0.1

        if opponent_id in self.coop_response_after_my_defect_count:
            coop_after_def = self.coop_response_after_my_defect_count[opponent_id][0]
            defect_after_def = self.coop_response_after_my_defect_count[opponent_id][1]
            total_after_def = coop_after_def + defect_after_def
            if total_after_def >= 3:
                coop_rate_after_def = coop_after_def / total_after_def
                if coop_rate_after_def > 0.8:
                    prob -= 0.15
                elif coop_rate_after_def > 0.6:
                    prob -= 0.05

        if opponent_id in self.overly_cooperative_suspects:
            suspect_score = self.overly_cooperative_suspects[opponent_id]
            if suspect_score > 2:
                prob += 0.1

        if len(self.recent_opp_actions_global) >= 10:
            global_coop_rate = sum(1 for a in self.recent_opp_actions_global if a == 'cooperate') / len(self.recent_opp_actions_global)
            if global_coop_rate > 0.7:
                prob += 0.05
            elif global_coop_rate < 0.3:
                prob -= 0.05

        adaptive_pun = self.adaptive_punishment.get(opponent_id, 0.0)
        adaptive_rew = self.adaptive_reward.get(opponent_id, 0.0)
        prob -= adaptive_pun * 0.25
        prob += adaptive_rew * 0.25

        risk = self.risk_assessment.get(opponent_id, 0.5)
        if risk > 0.7:
            prob -= 0.1
        elif risk < 0.3:
            prob += 0.1

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

