            elif my_action == 'defect' and opp_action == 'defect':
                self.mutual_defect_count[opponent_id] = self.mutual_defect_count.get(opponent_id, 0) + 1

            count = self.interaction_count.get(opponent_id, 0)
            old_rate = self.long_term_coop_rate.get(opponent_id, 0.5)
            new_count = count + 1
            new_rate = (old_rate * count + (1 if opp_action == 'cooperate' else 0)) / new_count
            self.long_term_coop_rate[opponent_id] = new_rate
            self.interaction_count[opponent_id] = new_count
            if new_count > 1:
                old_variance = self.coop_variance.get(opponent_id, 0.1)
                new_variance = ((count - 1) * old_variance + (1 if opp_action == 'cooperate' else 0 - new_rate) ** 2) / new_count
                self.coop_variance[opponent_id] = new_variance

            if opponent_id not in self.recent_coop_rate:
                self.recent_coop_rate[opponent_id] = [0.5] * self.recent_coop_window
            window = self.recent_coop_rate[opponent_id]
            window.append(1 if opp_action == 'cooperate' else 0)
            if len(window) > self.recent_coop_window:
                window.pop(0)
            self.recent_coop_rate[opponent_id] = sum(window) / len(window) if window else 0.5

            self.recent_interaction_count[opponent_id] = self.recent_interaction_count.get(opponent_id, 0) + 1

