        if self.adaptation_strength > 0:
            prob += self.adaptation_strength * 0.05
        elif self.adaptation_strength < 0:
            prob += self.adaptation_strength * 0.05

        prob = max(0.05, min(0.95, prob))
        return random.random() < prob

